/* SC-200 Cert Gauntlet — cards, domain 1: Manage a security operations environment */
/* Facts verified against learn.microsoft.com, Oct 2026. All prose original. */
export const SC200_CARDS_D1 = [
 /* ---------- xdrauto: Defender XDR automation & notifications ---------- */
 {c:"xdrauto",obj:"1.1.1",q:"Incident email notifications — where you create the rule",a:"#Settings > Microsoft Defender XDR > Email notifications > Incidents\nOne rule = recipients + filters (severity, device groups, sources)",s:"Defender XDR settings, Email notifications, Incidents tab",g:"notiftab",
  x:"Incident notifications are tenant-level rules in the Defender portal, not a per-user mailbox setting. Each rule names recipients and the filters that decide which new incidents trigger mail. The exam likes to contrast this tab with the Actions tab (response actions) and the Threat analytics tab (report updates), so remember that incidents, actions and threat analytics are three separate tabs under the same Email notifications page.",
  w:"Three tabs, one page: Incidents, Actions, Threat analytics."},
 {c:"xdrauto",obj:"1.1.1",q:"Incident notification rule — the filters you can set",a:"#Alert severity, device groups, service sources, detection sources\nOption to send only one email per incident",s:"Severity, device groups, service and detection sources",
  x:"A rule can be narrowed to specific severities (for example High only), to selected device groups, to particular service sources such as Defender for Endpoint, and to detection sources inside those services. A checkbox limits delivery to the first notification for an incident so updates do not spam the inbox. Stem wording such as 'notify the SOC only for high-severity incidents on the Finance device group' maps straight onto these filters.",
  w:"Filter by severity, group, source; optionally one mail per incident."},
 {c:"xdrauto",obj:"1.1.1",q:"Who can create Defender XDR email notification rules?",a:"#Manage security settings permission (Security Administrator or higher)\nWith RBAC, only for device groups the user manages",s:"Manage security settings; RBAC limits to managed groups",
  x:"Notification rules require the 'Manage security settings' permission, which Security Administrator and Global Administrator hold by default and which Unified RBAC can grant to a custom role. When device-group RBAC is in use, an analyst can only create, edit, delete or receive rules scoped to device groups they are permitted to manage. A question where a scoped analyst cannot see an org-wide rule is testing this boundary."},
 {c:"xdrauto",obj:"1.1.1",q:"Actions email notifications — what they report",a:"#Response actions completed or failed\nManual and/or automated (AIR, attack disruption) sources, filtered by action type and device group",s:"Completed or failed response actions, manual or automated",g:"notiftab",
  x:"The Actions tab sends mail when a response action finishes or fails. You choose the source (manual actions by analysts, automated actions from AIR and attack disruption, or both), the status (completed, failed, both), optional action types, and a device-group scope that can include all current and future groups. It needs the same Manage security settings permission as the other tabs. Note that response actions attached to custom detection rules are not covered by these notifications."},
 {c:"xdrauto",obj:"1.1.1",q:"Threat analytics email notifications — what you choose",a:"#All reports, specific report types, or specific tags (e.g. Ransomware)\nEmail notifications > Threat analytics tab",s:"New or updated threat analytics reports by type or tag",g:"notiftab",
  x:"The Threat analytics tab creates rules that mail recipients when Microsoft publishes or updates intelligence reports. You can subscribe to everything, to a report type, or to tags such as Ransomware or Activity group, then add recipients and send a test. Rule names accept only English letters and numbers. On the exam, 'be told when a new report about a threat actor is published' points here, not to incident or alert notifications.",
  w:"Reports, not incidents: threat analytics tab."},
 {c:"xdrauto",obj:"1.1.1",q:"Endpoint alert email notifications (Settings > Endpoints) — how they differ",a:"#Legacy per-alert mails from Defender for Endpoint\nSeverity + device groups; only Global Admin can target all devices",s:"Per-alert endpoint mails scoped by severity and group",
  x:"Besides the Defender XDR tabs, Defender for Endpoint still has its own Email notifications page under Settings > Endpoints > General. It fires per alert, with severity levels and device-group selection, and can include the device name and a portal link. Only a Global Administrator can choose all devices; other roles are limited to groups they manage. Exam stems that say 'alert' and 'endpoints settings' want this page; stems that say 'incident' want the XDR page.",
  w:"Endpoint page = alerts; XDR page = incidents."},
 {c:"xdrauto",obj:"1.1.1",q:"Test email in a notification rule — purpose",a:"#Confirms recipients and delivery before the rule goes live\nAvailable on incident, action and threat analytics rules",s:"Verifies delivery to recipients before saving",
  x:"Every notification flyout includes a send-test-email button. It proves the addresses are reachable and the mail is not filtered, which matters because rules are tenant-wide and silently failing mail is a common SOC gap. In a troubleshooting stem where recipients 'never receive notifications', the first checks are the rule's filters, the recipient's device-group permissions, and a test send."},
 {c:"xdrauto",obj:"1.1.2",q:"Alert tuning — what it is",a:"#Rules that automatically hide, resolve or reclassify matching alerts\nSettings > Microsoft Defender XDR > Alert tuning (successor of alert suppression)",s:"Rules that auto-hide or auto-resolve expected alerts",
  x:"Alert tuning lets you describe expected organizational behavior as conditions and tell Defender XDR what to do when a future alert matches. It replaced the older alert suppression feature and spans multiple Defender services rather than endpoints only. Typical stem: a scheduled admin script keeps raising the same alert and you must stop the noise without disabling detection — the answer is a tuning rule, not deleting the alert or changing the device group.",
  w:"Tuning = suppression grown up, across services."},
 {c:"xdrauto",obj:"1.1.2",q:"Alert tuning rule — condition types",a:"#Evidence types: file, process, scheduled task, AMSI script, WMI event, other IOCs\nCombine with AND / OR and grouping",s:"Evidence-based conditions joined with AND/OR",
  x:"Conditions describe the evidence that triggered the alert: a file hash or path, a process command line, a scheduled task, an AMSI script, a WMI event, or another indicator. Several conditions can be grouped with AND and OR to describe a precise situation, for example this process launched by this parent on devices in this group. The tighter the condition set, the less chance of hiding a genuine attack that merely resembles the benign activity."},
 {c:"xdrauto",obj:"1.1.2",q:"Alert tuning action: Hide alert",a:"#Suppresses the alert and stops incident creation (Defender for Endpoint alerts)\nData still lands in AlertInfo / AlertEvidence",s:"Alert never shows and no incident is created",g:"tuneact",
  x:"Hide alert is the strongest tuning action: matching Defender for Endpoint alerts are kept out of the queue and never create an incident. The underlying data remains in advanced hunting, so a hunter can still find hidden alerts in AlertInfo and AlertEvidence. Choose this when the behavior is fully understood and you need zero noise; choose Resolve when you still want a record in the queue."},
 {c:"xdrauto",obj:"1.1.2",q:"Alert tuning action: Resolve alert",a:"#Alert is created, then auto-set to Resolved\nThe related incident is resolved as well",s:"Alert appears but is closed automatically",g:"tuneact",
  x:"Resolve alert leaves an audit trail: the alert and its incident are created, then immediately marked resolved by the rule. Analysts can still open the record and see what happened, which suits scenarios where compliance wants evidence that the activity was reviewed. If the stem says the alerts must 'remain visible but not require triage', Resolve is the fit; if it says 'never appear', Hide is.",
  w:"Resolve keeps the paper trail; Hide removes it from the queue."},
 {c:"xdrauto",obj:"1.1.2",q:"Alert tuning action: Set as behavior",a:"#Matching signals become behaviors, not alerts\nStored in BehaviorInfo / BehaviorEntities; not for Defender for Cloud or Office 365",s:"Downgrades matches to behavior records instead of alerts",g:"tuneact",
  x:"Set as behavior converts future matches into behavior records that do not reach the alert queue or create incidents but remain queryable in BehaviorInfo and BehaviorEntities for hunting and context. It is not supported for alerts from Defender for Cloud or Defender for Office 365. The exam may present it as the middle ground between keeping noisy alerts and losing the telemetry entirely."},
 {c:"xdrauto",obj:"1.1.2",q:"Alert tuning rule scope — service sources",a:"#Pick which Defender services the rule applies to\nCan be created from the Alert tuning page or directly from an alert",s:"Applied per selected Defender service source",
  x:"When you build a tuning rule you choose the service sources it covers, such as Defender for Endpoint or Defender for Office 365, so one rule does not accidentally silence a different product's detection. Rules can also be started from an alert's details page, which prefills the evidence from that alert. A stem that asks to 'tune this specific alert without affecting other workloads' is pointing at the service-source selection."},
 {c:"xdrauto",obj:"1.1.2",q:"Legacy Defender for Endpoint alert suppression rules",a:"#Settings > Endpoints > Rules > Alert suppression\nEndpoint-only rules; editing can release previously suppressed alerts",s:"Endpoint-only rules under Endpoints > Rules",
  x:"Before alert tuning, Defender for Endpoint had its own suppression rules under Settings > Endpoints > Rules. The page still exists to view, enable, disable, edit and delete those rules and shows scope, action and matched-alert counts; when you edit a rule you can release alerts it previously suppressed. Exam questions that mention 'suppression' are usually old-style endpoint rules, while 'tuning' means the cross-service XDR feature.",
  w:"Suppression = endpoint legacy; tuning = XDR-wide."},
 {c:"xdrauto",obj:"1.1.2",q:"How Defender XDR correlates alerts into one incident",a:"#Shared entities, artifacts, time frame or attack sequence\nA sufficiently unique alert starts a new incident",s:"Shared entities, artifacts, timing or attack sequence",
  x:"The correlation engine looks for common users, devices, mailboxes, files, processes and senders across alerts within a time window, plus known multistage patterns such as a phishing mail followed by a click. Related alerts are appended to an existing incident; a sufficiently distinct alert opens a new one. On the exam, the concept explains why one incident can span endpoint, identity and email alerts and why you should investigate incidents rather than isolated alerts."},
 {c:"xdrauto",obj:"1.1.2",q:"'Restrict correlation to within scoped device groups' — effect",a:"#Prevents merging incidents whose devices sit in different device groups\nAdvanced features toggle; off by default",s:"Stops cross-device-group incident merging",
  x:"This advanced feature keeps incidents from being consolidated when their devices belong to different device groups, which matters for MSSPs or segmented SOC teams that must not see each other's incidents. It is not enabled by default. Stem signal: 'analysts in region A see alerts from region B inside their incidents' — the fix is this toggle, not more notification rules."},
 {c:"xdrauto",obj:"1.1.2",q:"When incidents will NOT auto-merge",a:"#One is closed, different owners, different classification or determination\nAlso different device groups (if restricted) or entity limits exceeded",s:"Closed, different owner, classification or determination",
  x:"Automatic merging stops when the two incidents disagree on status, assignment, classification or determination, when merging would exceed the entity limit, or when device-group restriction applies. Analysts can still merge up to five incidents manually after resolving those conflicts; the source incident gets a Redirected tag and its alerts, tags and comments move to the target. Exam stems about 'why were these not combined' want one of these blockers."},
 {c:"xdrauto",obj:"1.1.7",q:"Automated investigation and response (AIR) — what it does",a:"#Investigates alerts like a virtual analyst, gathers evidence, proposes remediation\nVerdicts: Malicious, Suspicious, No threats found",s:"Automatic investigation with verdicts and remediation",
  x:"When an alert creates an incident, AIR can start an automated investigation that examines files, processes, services, drivers and related entities across devices, identities and email. Each piece of evidence receives a verdict and malicious items get remediation actions such as quarantine, stop process, or isolate device, executed automatically or queued for approval depending on the automation level. The exam tests the levels, the Action center, and the fact that email remediation always needs approval.",
  w:"AIR = investigate, verdict, remediate (or ask)."},
 {c:"xdrauto",obj:"1.1.7",q:"Automation level: Full - remediate threats automatically",a:"#All remediation runs without approval\nActions logged in Action center History; recommended level",s:"Remediates everything automatically, no approvals",g:"airlevel",
  x:"Full automation lets AIR execute every remediation it decides on, recording each action in the Action center History tab where it can be reviewed and, where supported, undone. Microsoft recommends it and it is the default for tenants created on or after 16 August 2020 and for Defender for Business. Stem signal: 'minimize analyst effort' or 'remediate without manual approval' means Full."},
 {c:"xdrauto",obj:"1.1.7",q:"Automation level: Semi - require approval for all folders",a:"#Every remediation waits in Action center Pending\nPending actions expire after 7 days",s:"Approval needed for any file remediation",g:"airlevel",
  x:"At this level AIR still investigates, but each remediation on files in any folder is queued for an analyst to approve or reject in the Pending tab. Unapproved actions time out after seven days. This was the default for tenants created before 16 August 2020. The exam contrasts it with the two narrower Semi levels, which auto-remediate in some locations and only ask for others.",
  w:"'All folders' = ask about everything."},
 {c:"xdrauto",obj:"1.1.7",q:"Automation level: Semi - require approval for core folders remediation",a:"#Approval needed only for OS directories such as \\windows\\*\nFiles elsewhere are remediated automatically",s:"Asks only for files in operating-system folders",g:"airlevel",
  x:"Core folders are operating-system locations, for example anything under \\windows. With this level AIR auto-remediates files outside those directories but requires a human to approve changes inside them, protecting system stability while still handling most threats hands-free. Stem signal: 'automatically remediate user files but require approval for changes to Windows system folders'."},
 {c:"xdrauto",obj:"1.1.7",q:"Automation level: Semi - require approval for non-temp folders remediation",a:"#Auto-remediates only in temporary folders (temp, downloads, program files…)\nEverything else waits for approval",s:"Automatic only in temporary folders",g:"airlevel",
  x:"This is the most cautious Semi level: AIR acts on its own only in locations Microsoft classes as temporary, such as users' AppData\\Local\\Temp, Windows\\Temp, Downloads and Program Files, and queues everything else for approval. Compare with the core-folders level, which is the opposite emphasis. If a stem wants 'automatic cleanup of downloaded malware but approval for anything outside temp locations', this is the match.",
  w:"Non-temp = ask unless it is in a temp-style folder."},
 {c:"xdrauto",obj:"1.1.7",q:"Automation level: No automated response",a:"#Automated investigation does not run for the device group\nNo actions taken or queued; not recommended",s:"Disables automated investigation entirely",g:"airlevel",
  x:"Setting a device group to No automated response switches AIR off for those devices: no investigation, no pending actions, nothing in the Action center. Other protections such as antivirus still apply. Microsoft advises against it, and it also removes the group from automatic attack disruption containment. Exam stems about 'why did no automated investigation start for these servers' often resolve to this level on their device group."},
 {c:"xdrauto",obj:"1.1.7",q:"Where is the AIR automation level set?",a:"#Per device group: Settings > Endpoints > Device groups\nEach group chooses its own remediation level",s:"Per device group under Endpoints settings",
  x:"Automation levels are not a single tenant switch; they are a property of each Defender for Endpoint device group, configured under Settings > Endpoints > Permissions > Device groups. That is why a SOC can run Full on workstations and a Semi level on domain controllers. Any stem that asks for different automation behavior for different sets of devices is really asking you to create or edit device groups.",
  w:"Automation level lives on the device group."},
 {c:"xdrauto",obj:"1.1.7",q:"Action center — Pending tab",a:"#Remediation actions awaiting approval\nApprove or reject one at a time or in bulk for the same action type",s:"Queue of actions waiting for approval",g:"actctr",
  x:"The Pending tab under Actions and submissions > Action center lists every remediation AIR proposed under a Semi automation level plus email actions, which always wait for approval. Analysts review each action, approve or reject it, and can bulk-approve selections of the same type. Approving promptly matters because pending actions expire. Stem signal: 'the investigation is stuck at Pending approval'."},
 {c:"xdrauto",obj:"1.1.7",q:"Action center — History tab",a:"#Audit log of completed actions: AIR, manual, live response, antivirus\nStarting point for undoing an action",s:"Record of completed actions, with undo",g:"actctr",
  x:"History shows what already happened: remediation from automated investigations, manual actions on devices, files, emails and URLs, live response commands and antivirus actions, with who and when. Completed actions that support reversal, such as device isolation or app restriction, can be undone from here. On the exam, 'review what AIR did last night' is History; 'approve what AIR wants to do' is Pending.",
  w:"Pending = future, History = past (and undo)."},
 {c:"xdrauto",obj:"1.1.7",q:"Undoing a remediation action",a:"#Select the completed action in Action center History and choose Undo\nSupported for actions like isolate device and restrict code execution",s:"Reverse a completed action from the History tab",
  x:"Remediation is reversible for a defined set of actions. From the History tab you pick the action and undo it, for example releasing a device from isolation or removing an app-execution restriction that a Full-automation investigation applied. Not every action can be reversed, so the exam may ask which pane to use (History) and which actions qualify rather than simply whether undo exists."},
 {c:"xdrauto",obj:"1.1.7",q:"Email and content remediation in AIR — approval rule",a:"#Never executed automatically\nAll Defender for Office 365 remediation waits in the Action center",s:"Email actions always require approval",
  x:"Even with Full automation on every device group, AIR does not act on email or collaboration content on its own: soft-delete, move-to-junk and similar actions from Defender for Office 365 investigations are queued for the SOC to approve. Exam stems that claim 'the malicious messages were removed automatically by AIR' are describing something that does not happen; the correct flow is Pending approval in the Action center."},
 {c:"xdrauto",obj:"1.1.8",q:"Automatic attack disruption — what it does",a:"#Contains compromised devices and users mid-attack with high confidence\nLimits lateral movement; actions are reversible by the SOC",s:"Automatically contains assets during an active attack",
  x:"Attack disruption uses cross-workload XDR signals and Microsoft threat intelligence to recognise an in-progress campaign, such as human-operated ransomware or business email compromise, and immediately contain the assets the attacker controls. It acts before a human triages the incident, yet every action can be undone. Distinguish it from AIR: AIR investigates individual alerts after the fact; disruption stops an active, high-confidence attack chain."},
 {c:"xdrauto",obj:"1.1.8",q:"Attack disruption action: Contain device",a:"#Other onboarded devices block traffic to and from the suspect device\nNeeds Defender for Endpoint and standard device discovery",s:"Onboarded devices block the suspect device's traffic",g:"disruptact",
  x:"Contain device instructs every onboarded Defender for Endpoint device to drop communication with the compromised machine, which works even when that machine is unmanaged. The contained device itself keeps running. Device discovery must be in Standard mode for this to function. Compare with Isolate device, which cuts the suspect device off at its own network stack but keeps its link to the Defender service."},
 {c:"xdrauto",obj:"1.1.8",q:"Attack disruption action: Contain user",a:"#Blocks a compromised account's authentication, file and network access across devices\nRequires Sense agent 10.8470 or later",s:"Blocks a compromised identity on every onboarded device",g:"disruptact",
  x:"Contain user stops an attacker-controlled account from moving laterally by blocking its sign-ins and its SMB, RDP and similar activity on onboarded endpoints, without yet disabling the account in the directory. It needs a recent Defender for Endpoint sensor. A stem describing a service account being used for lateral movement with the requirement 'stop it immediately without disabling the account' points at this action."},
 {c:"xdrauto",obj:"1.1.8",q:"Attack disruption action: Disable user",a:"#Account disabled in Active Directory and/or Entra ID\nDefender for Identity sensors act on domain controllers for AD accounts",s:"Account disabled in AD and Entra via Defender for Identity",g:"disruptact",
  x:"Disable user removes the account's ability to sign in. For on-premises accounts, Defender for Identity triggers the disable on domain controllers that run a sensor; for synced accounts it disables in both AD and Entra ID; cloud-only accounts are handled through a Microsoft-managed Defender for Identity enterprise application. Stem signal: hybrid environment plus 'the account must be disabled on-premises as well as in the cloud'.",
  w:"Hybrid disable = DfI sensor on the DC does the work."},
 {c:"xdrauto",obj:"1.1.8",q:"How attack disruption shows on an incident",a:"#'Attack Disruption' tag in the queue and on the incident\nYellow banner; API titles get the suffix (attack disruption)",s:"Incident tagged Attack Disruption with a banner",
  x:"Disrupted incidents carry a dedicated tag visible in the incident queue and on the incident page, together with a banner that explains the automatic action and asset status markers in the graph such as 'device contained' or 'account disabled'. Incidents fetched through the API carry the suffix in their title. Exam stems describing a tag you did not add yourself are usually about this feature."},
 {c:"xdrauto",obj:"1.1.8",q:"Attack disruption prerequisites",a:"#Defender XDR workloads deployed; device groups not set to No automated response\nStandard device discovery for Contain device",s:"Deployed workloads, automation enabled, standard discovery",
  x:"Disruption needs the relevant Defender products deployed (Endpoint for device actions, Identity for identity actions, Office 365 and Cloud Apps for their signals) and the device groups involved must have an automation level other than No automated response. Contain device also requires device discovery in Standard mode. Configuration lives under Settings > Endpoints > Advanced features and needs Security Administrator or similar."},
 {c:"xdrauto",obj:"1.1.8",q:"Attack disruption exclusions",a:"#Users, devices or IPs you never want contained automatically\nSeparate from selective-isolation exclusions",s:"Assets exempt from automatic containment",
  x:"Critical assets such as a backup server, a break-glass account or a monitoring appliance can be excluded so that disruption never contains or disables them. Exclusions are configured in the attack disruption settings. Do not confuse them with selective isolation exclusions, which define which processes and destinations an isolated device may still reach. Stem signal: 'ensure the domain controller is never automatically contained'.",
  w:"Exclude the asset you cannot afford to have contained."},
 /* ---------- dfecfg: Defender for Endpoint configuration ---------- */

 {c:"dfecfg",obj:"1.1.3",q:"Advanced features page — where it is",a:"#Settings > Endpoints > General > Advanced features\nTenant-wide toggles for Defender for Endpoint capabilities",s:"Tenant-wide toggle list under Endpoints > General",
  x:"Advanced features is the single page of on/off switches that unlock tenant-wide Defender for Endpoint behavior: live response, EDR in block mode, tamper protection, custom network indicators, web content filtering, device discovery, Intune and Defender for Cloud Apps connections, preview features and more. The exam expects you to know which capability is a toggle here versus a per-policy or per-device-group setting, and the path to reach it.",
  w:"If it is a tenant-wide switch, it is probably on Advanced features."},
 {c:"dfecfg",obj:"1.1.3",q:"Advanced feature: Live response",a:"#Lets permitted users open remote shell sessions on devices\nSeparate toggle for servers; a third allows unsigned scripts",s:"Enables remote shell sessions to devices",g:"advfeat",
  x:"Turning on Live response allows analysts holding the live response permission to connect to an onboarded device and run commands such as collecting files or running scripts. Servers need the additional 'Live response for servers' toggle, and 'Allow unsigned script execution in live response' is a third, riskier switch for scripts that are not signed. A stem where an analyst 'cannot start a session on a Windows Server' usually lacks the server toggle."},
 {c:"dfecfg",obj:"1.1.3",q:"Advanced feature: Allow unsigned script execution in live response",a:"#Permits running unsigned PowerShell scripts in a session\nOff by default; raises risk",s:"Unsigned scripts allowed in live response",g:"advfeat",
  x:"By default a live response session only runs scripts that are signed. This toggle lifts that restriction so analysts can upload and execute ad-hoc, unsigned scripts from the library. Because it widens what an attacker with portal access could do, Microsoft keeps it off by default. Exam signal: 'the custom .ps1 fails to run in live response' with no signing infrastructure mentioned."},
 {c:"dfecfg",obj:"1.1.3",q:"Advanced feature: Enable EDR in block mode",a:"#Defender AV remediates EDR behavioral detections even in passive mode\nFor devices where a non-Microsoft AV is primary",s:"EDR remediation when Defender AV is passive",g:"advfeat",
  x:"EDR in block mode lets Defender for Endpoint act on post-breach behavioral detections when Microsoft Defender Antivirus is running passively behind another vendor's AV. Blocked items show as Blocked or Prevented in the Action center. It needs Plan 2, cloud protection and current platform versions. If the stem says 'third-party antivirus' and asks how to still get automated blocking from Defender, this toggle is the answer.",
  w:"Third-party AV in front? EDR in block mode still bites."},
 {c:"dfecfg",obj:"1.1.3",q:"Advanced feature: Enable tamper protection",a:"#Locks Defender AV settings against local or malicious changes\nTenant-wide switch; Intune can scope it instead",s:"Prevents security settings being switched off",g:"advfeat",
  x:"Tamper protection stops real-time protection, cloud protection, behavior monitoring, security intelligence updates and similar settings from being disabled by local admins, scripts or malware. The portal toggle applies to the whole tenant, while Intune or Configuration Manager tenant attach can target specific groups and exclude devices. Stem signal: 'malware disabled real-time protection on several devices' — the control that would have prevented it is tamper protection."},
 {c:"dfecfg",obj:"1.1.3",q:"Advanced feature: Automatically resolve alerts",a:"#Resolves alerts when AIR finds no threat or remediates it\nWithout it, those alerts stay open for manual closure",s:"Closes alerts after a clean or remediated investigation",g:"advfeat",
  x:"With this switch on, an alert whose automated investigation ends in 'No threats found' or in successful remediation is set to Resolved without an analyst touching it. If it is off, the alert remains in the queue even though the investigation finished. A stem that says 'alerts remediated by AIR remain open' is pointing at this toggle rather than at the automation level."},
 {c:"dfecfg",obj:"1.1.3",q:"Advanced feature: Allow or block file",a:"#Enables file-hash indicators that stop files being read, written or run\nPrerequisite for block/allow file actions",s:"Unlocks file-hash allow and block indicators",g:"advfeat",
  x:"Allow or block file turns on the ability to create file indicators that prevent a given hash from executing across the organization, or to explicitly allow a file Defender would otherwise flag. It is a prerequisite for the 'Block file' response action and for file-hash entries on the Indicators page. Stem signal: 'the Block option is greyed out on the file page' means this toggle is off."},
 {c:"dfecfg",obj:"1.1.3",q:"Advanced feature: Custom network indicators",a:"#Allows IP, URL and domain indicators to be enforced\nRelies on network protection and SmartScreen",s:"Enables IP, URL and domain indicators",g:"advfeat",
  x:"Custom network indicators unlocks the IP addresses and URLs/Domains tabs of the Indicators page so the SOC can allow, warn on or block destinations. Enforcement in non-Microsoft browsers depends on network protection in block mode; Microsoft Edge uses SmartScreen. Stem signal: a request to block a command-and-control domain on all endpoints — first the toggle, then the indicator."},
 {c:"dfecfg",obj:"1.1.3",q:"Advanced feature: Web content filtering",a:"#Block website categories (adult, gambling, hacking, streaming…) per device group\nReports under Web protection",s:"Category-based website blocking by device group",g:"advfeat",
  x:"Web content filtering lets you build policies that block parent categories such as Adult content, High bandwidth, Legal liability, Leisure and Uncategorized, scoped to device groups. Multiple policies on one group resolve to the most restrictive. Enforcement again needs network protection or SmartScreen. Distinguish from indicators: indicators target specific URLs, filtering targets whole categories.",
  w:"Indicators = this URL; web content filtering = this kind of site."},
 {c:"dfecfg",obj:"1.1.3",q:"Advanced feature: Device discovery",a:"#Finds unmanaged devices on the corporate network\nBasic (passive) or Standard (active, default) mode",s:"Discovers unmanaged devices via onboarded ones",g:"advfeat",
  x:"Device discovery uses onboarded endpoints as sensors to find printers, IoT, network gear and un-onboarded computers. Basic mode only listens; Standard mode, the default, actively probes to enrich the inventory and can exclude devices or subnets. Standard discovery is also required for attack disruption's Contain device action. Stem signal: 'identify devices that are not onboarded' or 'contain an unmanaged device'."},
 {c:"dfecfg",obj:"1.1.3",q:"Advanced feature: Microsoft Intune connection",a:"#Shares device risk with Intune for Conditional Access\nAlso underpins security settings management",s:"Integrates risk signals with Intune",g:"advfeat",
  x:"The Intune connection lets Defender for Endpoint report machine risk levels into Intune compliance policies so Conditional Access can block risky devices, and it is a prerequisite for managing endpoint security policies from the Defender portal on devices that are not Intune-enrolled. Stem signal: 'block access to Microsoft 365 from devices with a high risk level' — enable this toggle, then build compliance and Conditional Access policies."},
 {c:"dfecfg",obj:"1.1.3",q:"Advanced feature: Microsoft Defender for Cloud Apps integration",a:"#Forwards endpoint network signals to Defender for Cloud Apps\nPowers cloud discovery without a log collector",s:"Sends endpoint traffic data to Cloud Apps discovery",g:"advfeat",
  x:"With this toggle, Defender for Endpoint streams its view of which cloud apps devices talk to into Defender for Cloud Apps, so shadow-IT discovery works for roaming devices without firewall or proxy logs. It also lets Cloud Apps unsanctioned-app blocks be enforced on endpoints as indicators. Stem signal: 'discover cloud app usage on laptops outside the corporate network'."},
 {c:"dfecfg",obj:"1.1.3",q:"Advanced feature: Share endpoint alerts with Microsoft Compliance Center",a:"#Sends endpoint alerts to Purview for insider risk management\nSeparate from the unified audit log toggle",s:"Feeds endpoint alerts into Purview insider risk",g:"advfeat",
  x:"This switch forwards Defender for Endpoint security alerts to Microsoft Purview so insider risk management policies can use them as indicators. It is distinct from 'Enable the unified audit log', which exposes Defender events to Purview Audit search. Stem signal: 'insider risk policies should factor in endpoint security violations' — this is the toggle, not an analytics rule."},
 {c:"dfecfg",obj:"1.1.4",q:"Indicators page — the four indicator types",a:"#File hashes (SHA1/SHA256), IP addresses, URLs/domains, certificates\nSettings > Endpoints > Rules > Indicators",s:"Hashes, IPs, URLs/domains, certificates",
  x:"Indicators of compromise are custom allow/block entries managed under Rules > Indicators. File hashes cover SHA1 and SHA256, IP indicators are single external addresses with no CIDR, URL and domain entries handle web destinations, and certificate indicators allow or block signed binaries by signer. Each entry carries an action, severity, optional expiry and a device-group scope. The exam tests which type fits the artifact in the stem."},
 {c:"dfecfg",obj:"1.1.4",q:"Indicator actions — allow, audit, warn, block, block and remediate",a:"#Allow > Warn > Block precedence when entries conflict\nBlock and remediate only for file indicators",s:"Allow beats warn beats block; remediate is file-only",
  x:"An indicator's action decides what happens on a match: Allow suppresses detection, Audit only logs, Warn shows an overridable prompt, Block prevents the file or connection, and Block and remediate also quarantines, which is only available for files. If several indicators target the same artifact, Allow wins over Warn, which wins over Block. Stem signal: 'the site is still reachable despite a block indicator' — look for a conflicting allow."},
 {c:"dfecfg",obj:"1.1.4",q:"Network indicator prerequisites",a:"#Custom network indicators toggle on, network protection in block mode\nDefender AV active with cloud protection; external IPs only",s:"Toggle plus network protection in block mode",
  x:"IP, URL and domain indicators only enforce when the Custom network indicators advanced feature is on and network protection runs in block mode for non-Microsoft browsers, with Microsoft Defender Antivirus active, behavior monitoring and cloud-delivered protection enabled. Internal IP ranges and CIDR blocks are not supported. Propagation can take up to 48 hours. Troubleshooting stems about indicators not blocking usually hide one of these prerequisites.",
  w:"No network protection, no network indicator."},
 {c:"dfecfg",obj:"1.1.4",q:"Indicator scope and expiration",a:"#Scope: all devices or selected device groups\nExpiry date optional; import up to 500 per CSV",s:"Device-group scope plus optional expiry date",
  x:"Each indicator can apply to the whole organization or only to chosen device groups, and may carry an expiration time after which it stops applying. Indicators can be created singly, imported from CSV (500 per file) or pushed through the API, and can optionally generate an alert with a title, severity, category and MITRE technique. Stem signal: 'block the hash only on the Finance workstations for 30 days' combines scope and expiry."},
 {c:"dfecfg",obj:"1.1.4",q:"Automation folder exclusions",a:"#Folders AIR skips during automated investigation\nFields: folder (trailing wildcard), extensions, file names, description",s:"Paths that automated investigation ignores",
  x:"Under Settings > Endpoints > Rules, automation folder exclusions tell AIR not to examine or remediate content in given folders, optionally narrowed by extension or file name so attackers cannot hide in a broad exclusion. Excluded files are still scanned by antivirus, and live response reports 'File is excluded' when asked to collect them. Stem signal: 'prevent automated investigation from quarantining the build server's output directory'."},
 {c:"dfecfg",obj:"1.1.4",q:"Automation uploads (content analysis)",a:"#Which file and attachment extensions AIR submits to the cloud\nSettings > Endpoints > Rules > Automation uploads",s:"Extensions AIR sends to cloud for analysis",
  x:"Automation uploads controls whether suspicious files and email attachments found during an automated investigation are sent to Microsoft's cloud for deeper inspection, and which extensions qualify. Submitted files are stored for six months. The special entry of a double quote represents files with no extension. Stem signal: 'ensure .bat files found by AIR are analyzed in the cloud' is this page, not an indicator."},
 {c:"dfecfg",obj:"1.1.5",q:"Defender for Endpoint data retention — the default",a:"#Data is kept for 180 days and visible across the portal\nAdvanced hunting queries reach 30 days of raw data",s:"180 days in the portal, 30 days in advanced hunting",
  x:"Defender for Endpoint and the wider Defender XDR portal retain data for 180 days, with advanced hunting able to query the last 30 days of raw events. The Data retention page under Settings > Endpoints > General lets you set the retention period for the tenant. If longer hunting history is needed, the exam expects you to stream the tables to Microsoft Sentinel rather than change the Defender default.",
  w:"180 portal, 30 hunting; longer means Sentinel."},
 {c:"dfecfg",obj:"1.1.5",q:"Data storage location for Defender for Endpoint",a:"#Chosen at provisioning from supported geos (EU, UK, US, AU, CH, IN, UAE…)\nCannot be moved afterwards",s:"Geo fixed at tenant provisioning",
  x:"When the tenant is first set up, Defender data is pinned to a geography such as the European Union, United Kingdom, United States, Australia, Switzerland, India or the UAE, and the region is shown under Settings > Microsoft Defender XDR > Account. The location cannot be changed later. Compliance-flavored stems that demand data stay in a particular region are answered by provisioning in that geo, not by a retention setting."},
 {c:"dfecfg",obj:"1.1.5",q:"Collect investigation package — what it gathers",a:"#Autoruns, installed programs, network connections, prefetch, processes, scheduled tasks, security event log, services, SMB sessions, users\nZip downloaded from the device page / Action center",s:"Forensic zip of device state and logs",
  x:"The investigation package is a response action that bundles forensic artifacts from a device into a downloadable zip: autostart entries, program list, network and ARP/DNS data, prefetch, running processes, scheduled tasks, the security event log, services, SMB sessions, system information, temp directories, users and groups and Defender support logs. It is the exam's go-to for 'collect evidence without a live response session'.",
  w:"Package = snapshot of the device, no shell needed."},
 {c:"dfecfg",obj:"1.1.5",q:"Download quarantined files — advanced feature",a:"#Backs up quarantined files so analysts can retrieve them\nFiles downloaded from a secure, compliant location",s:"Retrieve files Defender AV quarantined",
  x:"This toggle makes Defender for Endpoint keep a copy of files that Microsoft Defender Antivirus quarantines so an analyst can download them later for analysis. Without it, the quarantined sample stays only on the device. Stem signal: 'obtain a copy of the malware that was quarantined on a laptop that is now offline' — the file is only retrievable if this feature was already on."},
 {c:"dfecfg",obj:"1.1.6",q:"Attack surface reduction (ASR) rules — modes",a:"#Not configured/Disabled (0), Block (1), Audit (2), Warn (6)\nSet per rule; test in Audit before Block",s:"Disabled, Block, Audit, Warn per rule",g:"asrmode",
  x:"Each ASR rule runs in one of four modes. Audit records what would have been blocked without stopping it, Block enforces, Warn blocks but lets the user bypass, and Disabled turns the rule off. Microsoft's deployment guidance is to run rules in Audit, review the ASR report, add exclusions, then move to Block. The numeric values matter when the stem shows Intune or PowerShell configuration.",
  w:"0 off, 1 block, 2 audit, 6 warn."},
 {c:"dfecfg",obj:"1.1.6",q:"ASR rules that cannot use Warn mode",a:"#Block credential stealing from LSASS\nBlock Office applications from injecting code into other processes",s:"LSASS credential theft and Office code injection",g:"asrmode",
  x:"Warn mode gives users a bypass prompt, which is unsafe for two rules: the one protecting the Local Security Authority Subsystem from credential dumping and the one stopping Office apps from injecting into other processes. For those, only Audit or Block apply. An exam stem that tries to set Warn on either is describing an unsupported configuration."},
 {c:"dfecfg",obj:"1.1.6",q:"ASR rule: Block all Office applications from creating child processes",a:"#Stops Word, Excel, PowerPoint etc. spawning other executables\nClassic defense against macro droppers",s:"Office apps may not spawn child processes",
  x:"This rule prevents Office applications from launching child processes such as PowerShell or cmd, which is how most macro-based droppers start their payload. It supports Audit, Block and Warn and accepts exclusions. On the exam, 'users open a malicious document and PowerShell runs' is the fingerprint for this rule; a sibling rule, 'Block Office applications from creating executable content', targets files written to disk instead."},
 {c:"dfecfg",obj:"1.1.6",q:"ASR rule: Block credential stealing from the Windows local security authority subsystem",a:"#Protects LSASS memory from tools like Mimikatz\nSupports Audit and Block only",s:"Prevents LSASS memory credential dumping",
  x:"This rule blocks untrusted processes from reading LSASS memory, the usual way attackers harvest credentials for lateral movement. It is one of two rules without Warn mode and has limited exclusion support. Stem signal: 'prevent credential dumping on workstations' or any mention of lsass.exe access by a suspicious tool."},
 {c:"dfecfg",obj:"1.1.6",q:"ASR rule: Block executable content from email client and webmail",a:"#Stops executables delivered by Outlook or webmail from running\nCovers .exe, .dll, .scr and script files",s:"Blocks executables that arrived via email",
  x:"The rule prevents executable files and scripts that were delivered through Outlook or popular webmail from running, cutting off a common initial-access path even if the mail filter missed it. Stem signal: 'users run an attachment received by email'. Compare with 'Block JavaScript or VBScript from launching downloaded executable content', which targets browser-delivered scripts."},
 {c:"dfecfg",obj:"1.1.6",q:"ASR rule: Use advanced protection against ransomware",a:"#Cloud-backed check that blocks files resembling ransomware\nRequires cloud-delivered protection",s:"Cloud-assisted block of ransomware-like files",
  x:"This rule uses client and cloud heuristics to stop files that look like ransomware from executing unless they are known trusted or sufficiently prevalent. It depends on cloud-delivered protection being on. Stem signal: a scenario demanding an endpoint-level ransomware safeguard beyond signatures. Note it is distinct from controlled folder access, which protects folders rather than blocking the executable."},
 {c:"dfecfg",obj:"1.1.6",q:"ASR exclusions",a:"#Exclude files and folders from a rule to fix false positives\nPer-rule exclusions supported for many rules; added after Audit review",s:"Files or folders exempt from an ASR rule",
  x:"When Audit mode shows a line-of-business app tripping a rule, you add an exclusion so the rule ignores that file or folder, then move the rule to Block. Many rules support per-rule exclusions; some have limited exclusion support. Exclusions are configured in the same Intune or Defender-portal policy as the rules. Stem signal: 'enable the rule in block mode without breaking the accounting application'."},
 {c:"dfecfg",obj:"1.1.6",q:"Endpoint security policies in the Defender portal",a:"#Endpoints > Configuration management > Endpoint security policies\nAV, AV exclusions, firewall, EDR, ASR, device control, update controls",s:"Create AV, firewall, EDR and ASR policies from Defender",
  x:"The Defender portal can create and assign the same endpoint security policy types Intune offers — antivirus, antivirus exclusions, firewall and firewall rules, endpoint detection and response, attack surface reduction, device control, Defender update controls — to both Intune-enrolled and Defender-managed devices from one console. Stem signal: 'manage ASR rules without granting the Intune administrator role'."},
 {c:"dfecfg",obj:"1.1.6",q:"Security settings management — Intune-enrolled vs Defender-managed devices",a:"#Defender-managed devices are not enrolled in Intune but still receive policies\nAssign to Entra device groups only (no user groups)",s:"Policies for non-enrolled devices via Entra device groups",
  x:"Security settings management lets a device onboarded to Defender for Endpoint but not enrolled in Intune receive endpoint security policies, after the Intune connection is enabled and the feature turned on. Such devices must be targeted through Microsoft Entra device groups; user-group assignment works only for Intune-enrolled devices, and device control policies apply only to enrolled devices. Stem signal: 'servers that are not managed by Intune must receive the ASR policy'.",
  w:"Not enrolled? Device groups only."},
 {c:"dfecfg",obj:"1.1.9",q:"Device groups — what they control",a:"#Automation level, RBAC access, and scoping for policies and filters\nSettings > Endpoints > Permissions > Device groups",s:"Automation level and access per set of devices",
  x:"A device group is the unit of policy in Defender for Endpoint. It carries the AIR remediation level, the Microsoft Entra user groups that may access its devices through RBAC, and it scopes notifications, indicators, web content filtering and reports. Up to 2,000 groups per tenant are allowed. Almost every 'different behavior for different devices' stem resolves to creating a group with the right rule, rank and level.",
  w:"Device group = automation level + who may see it."},
 {c:"dfecfg",obj:"1.1.9",q:"Device group membership rules",a:"#Match on device name, domain, tag, OS platform\nAll conditions must match; up to 10 values per property",s:"Name, domain, tag, OS conditions (AND)",
  x:"Membership is dynamic: you write conditions on device name, domain, tags and operating system, and every condition must be true for a device to join. Each property accepts up to ten values combined with OR. Tags are the most flexible lever because they can be set by registry, Intune, API or portal. Stem signal: 'all Windows Server devices in the Fabrikam domain tagged Finance' is a single group rule."},
 {c:"dfecfg",obj:"1.1.9",q:"Device group rank — how overlaps resolve",a:"#Rank 1 is evaluated first; a device joins only the highest-ranked match\nUngrouped devices catch everything else",s:"Highest-ranked matching group wins",
  x:"Groups are ordered. When a device satisfies several groups' rules it lands in the one with the best rank, so specific groups must be ranked above broad ones. The built-in Ungrouped devices group collects every device that matches nothing; its rank cannot change and it cannot be deleted, though its automation level and access can be edited. Stem signal: 'the servers ended up in the wrong group' means fix the rank.",
  w:"Specific above general, or the broad group swallows everything."},
 {c:"dfecfg",obj:"1.1.9",q:"Assigning access to a device group",a:"#Add Microsoft Entra user groups that already hold a Defender for Endpoint role\nNo groups assigned = all users can access",s:"Entra groups with RBAC roles see the group's devices",
  x:"With RBAC turned on, each device group lists the Entra user groups allowed to see and act on its devices; those user groups must already be assigned a role under Settings > Endpoints > Permissions > Roles. If no user group is assigned, the device group is visible to everyone with portal access. Stem signal: 'the regional team must only see their own devices' means role + device group assignment.",
  w:"Role first, then device group."},
 {c:"dfecfg",obj:"1.1.9",q:"Defender for Endpoint RBAC role permissions",a:"#View data, Alerts investigation, Active remediation actions, Live response (basic/advanced), Manage security settings, Manage portal system settings\nSettings > Endpoints > Permissions > Roles",s:"Granular permissions like view, investigate, remediate",
  x:"Custom roles bundle permissions: viewing security operations or vulnerability data, managing alerts and running scans or collecting packages, taking response actions and approving remediation, live response basic or advanced commands, managing security settings such as suppression and onboarding, and managing portal system settings, which only the Administrator role holds. Since February 2025, new tenants use Unified RBAC instead of these product-specific roles."},
 {c:"dfecfg",obj:"1.1.9",q:"Basic permissions: Security Reader vs Security Administrator",a:"#Security Reader: read-only, no device inventory\nSecurity Administrator / Global Administrator: full access",s:"Reader reads; Security Admin does everything",
  x:"Before RBAC is enabled, Defender for Endpoint falls back to Microsoft Entra roles: Security Administrator and Global Administrator have full control while Security Reader can only read and cannot view the device list. Microsoft recommends switching to RBAC with custom roles and device groups for least privilege. Stem signal: 'a Security Reader cannot see devices' is expected behavior, not a bug."},
 {c:"dfecfg",obj:"1.1.9",q:"Microsoft Defender Unified RBAC — the idea",a:"#One permission model across Defender workloads and Sentinel\nPermission groups: Security operations, Security posture, Authorization and settings",s:"Single cross-workload role model in the Defender portal",
  x:"Unified RBAC replaces each product's separate role model with custom roles defined once in the Defender portal and scoped to data sources, device groups and Defender for Identity OUs. Permissions are grouped into security operations, security posture, and authorization and settings. Each workload must be activated before unified roles apply, and Entra Global Administrators do not inherit permissions automatically. New Defender for Endpoint tenants have used it by default since 2025."},
 {c:"dfecfg",obj:"1.1.9",q:"Device tags — ways to apply them",a:"#Portal device page, API, dynamic rules, registry DeviceTagging key, Intune OMA-URI, config profiles\nTags feed device-group rules",s:"Portal, API, registry, Intune or dynamic rules",
  x:"Tags label devices with business context and are the usual input to device-group membership. They can be added manually on a device page, in bulk through the API, automatically with dynamic asset rules, via the DeviceTagging registry value on Windows, through an Intune custom OMA-URI, or with macOS/Linux configuration profiles. Stem signal: 'tag devices during imaging so they auto-join a group' points at the registry or Intune method."},
 {c:"dfecfg",obj:"1.1.9",q:"Onboarding methods for Windows devices",a:"#Local script (max 10 devices), Group Policy, Configuration Manager, Intune/MDM, VDI script\nServers: Defender for Cloud or Azure Arc",s:"Script, GPO, ConfigMgr, Intune, VDI, Arc",
  x:"Settings > Endpoints > Device management > Onboarding hands out packages per method: a local script for small pilots, Group Policy and Configuration Manager for domain fleets, Intune for MDM-managed devices, a script tailored to non-persistent VDI, and Defender for Cloud or Azure Arc for servers. You also choose standard or streamlined connectivity. Stem signal: a device count or management tool in the scenario picks the method."},
 /* ---------- sentauto: Sentinel automation rules & playbooks ---------- */
 {c:"sentauto",obj:"1.1.10",q:"Automation rule — what it is",a:"#Central, no-code rule: trigger + conditions + ordered actions\nHandles triage and can call playbooks",s:"Trigger, conditions and actions without a playbook",
  x:"Automation rules are Microsoft Sentinel's lightweight SOAR layer. One rule names a trigger, a set of conditions on the incident or alert, and an ordered list of actions such as assigning an owner, changing status or severity, adding tags or tasks, and running playbooks. They apply across many analytics rules at once, which is why the exam prefers them over editing each analytics rule. Stem signal: 'automatically assign' or 'automatically close' without a Logic App.",
  w:"Automation rule first; playbook only when you need external logic."},
 {c:"sentauto",obj:"1.1.10",q:"Automation rule trigger: When incident is created",a:"#Fires once when a new incident appears\nIncludes incidents synced from Defender XDR and manual incidents",s:"Runs on new incidents only",g:"autotrig",
  x:"The incident-created trigger is the default and most common choice. It runs once for each new incident regardless of whether an analytics rule, the Defender XDR connector or an analyst created it. Rules on this trigger run before any update-trigger rules on the same incident. Choose it for initial triage: assignment, tagging, severity adjustments and enrichment playbooks."},
 {c:"sentauto",obj:"1.1.10",q:"Automation rule trigger: When incident is updated",a:"#Fires on status, owner, severity, alert, comment, tag or tactic changes\nCondition can test what changed and who changed it",s:"Runs when an existing incident changes",g:"autotrig",
  x:"The incident-updated trigger reacts to changes rather than creation. Conditions can specify the property that changed, its before and after values, and the updater, for example a user, a playbook, an automation rule or alert grouping. Typical exam use: keep an external ticketing system in sync when status changes, or notify a team when severity is raised. Note that in the Defender portal rapid successive changes may be collapsed into the latest one.",
  w:"Updated = react to a change, and you can test 'changed from/to'."},
 {c:"sentauto",obj:"1.1.10",q:"Automation rule trigger: When alert is created",a:"#Fires per alert from Scheduled or NRT analytics rules\nUsed when incidents are disabled or created elsewhere",s:"Runs on alerts before any incident exists",g:"autotrig",
  x:"The alert trigger lets you act on individual alerts, which matters when the analytics rule has incident creation turned off, when the workspace is onboarded to the Defender portal (where Sentinel does not create incidents itself), or when you want to enrich an alert before incidents are built. Only alert-trigger playbooks can be attached. Stem signal: 'run a playbook for every alert even if no incident is created'."},
 {c:"sentauto",obj:"1.1.10",q:"Automation rule conditions — what you can test",a:"#Analytics rule name, incident provider, severity, status, tactics, tags, entities, custom details\nOperators: equals, contains, starts/ends with and negations",s:"Rule name, provider, severity, tags, entities, details",
  x:"Conditions narrow when a rule fires. You can match on which analytics rule raised the incident, the provider, severity and status, MITRE tactics, tags, entity properties such as account name or IP, and custom details. Tag conditions can evaluate any single tag or the whole collection. Stems that describe a very specific subset of incidents expect you to build the matching condition rather than a new analytics rule."},
 {c:"sentauto",obj:"1.1.10",q:"Automation rule actions",a:"#Assign owner, change status, change severity, add tags, add task, run playbook\nActions execute in the order listed",s:"Owner, status, severity, tags, tasks, playbooks",
  x:"Besides calling a playbook, an automation rule can itself assign the incident to a user or group, set status including closing with a classification and comment, change severity, add tags, and add incident tasks as a checklist for the analyst. Actions run sequentially, so a status change before a playbook means the playbook sees the new state. Stem signal: 'close as benign positive automatically' is a status action, no playbook needed."},
 {c:"sentauto",obj:"1.1.10",q:"Automation rule order",a:"#Rules run sequentially by Order number, lowest first\nLater rules evaluate the incident as earlier rules left it",s:"Lower order number runs earlier",
  x:"Each rule has an Order value. Creation-trigger rules run first in order, then update-trigger rules in order; rules sharing a number run in random sequence. Because a later rule sees the incident after earlier rules changed it, a rule that lowers severity can prevent a following rule whose condition requires Medium or higher from firing. Exam stems about a rule 'that never runs' often hide an ordering interaction.",
  w:"Order matters: rule 1's change can switch off rule 2's condition."},
 {c:"sentauto",obj:"1.1.10",q:"Automation rule expiration",a:"#Optional date after which the rule disables itself\nUseful for pen tests, maintenance windows, temporary staff",s:"Self-disables on a set date",
  x:"An expiration date lets you build time-boxed automation, for example auto-closing alerts from a known penetration test next week, or routing incidents to a consultant for a month. When the date passes the rule stops applying without anyone remembering to remove it. Stem signal: 'suppress incidents from the red-team exercise scheduled for 1–5 November' means an automation rule with an expiration, not deleting analytics rules."},
 {c:"sentauto",obj:"1.1.10",q:"Incident suppression with an automation rule",a:"#Condition on the noisy pattern, action: change status to Closed with a reason\nCan be created from the Incidents page",s:"Auto-close known false positives by condition",
  x:"To silence a recurring false positive without disabling the detection, create an automation rule whose conditions match the pattern (rule name, entity, tag) and whose action closes the incident with a classification such as Benign positive. It can be built directly from an incident so the conditions are prefilled. Compare with Defender XDR alert tuning, which does the same for Defender alerts, and with analytics rule suppression, which pauses the query instead."},
 {c:"sentauto",obj:"1.1.10",q:"Permission Sentinel needs to run playbooks from automation rules",a:"#Microsoft Sentinel Automation Contributor on the playbooks' resource group\nGranted to the Sentinel service identity via Manage playbook permissions",s:"Automation Contributor on the playbook resource group",
  x:"Automation rules run playbooks under Sentinel's own service identity, not the analyst's. That identity must hold the Microsoft Sentinel Automation Contributor role on each resource group that holds playbooks, granted through the Manage playbook permissions pane by an Owner or User Access Administrator. In multi-tenant setups the grant is made in the tenant where the playbook lives. Stem signal: 'the playbook runs manually but not from the automation rule'.",
  w:"Manual works, automatic fails? Sentinel lacks Automation Contributor."},
 {c:"sentauto",obj:"1.1.10",q:"Where can automation rules be created?",a:"#Automation page, the analytics rule wizard, or from an incident\nExportable as ARM templates",s:"Automation page, rule wizard, incident page",
  x:"Rules can be authored centrally on the Automation page, inline inside the analytics rule wizard's automated response tab (scoped to that rule), or from the Incidents page to suppress a pattern you are looking at. They can be exported to ARM templates for source control and redeployment. On the exam, a stem about reusing automation across workspaces suggests ARM export or workspace manager."},
 {c:"sentauto",obj:"1.1.11",q:"Sentinel playbook — what it is",a:"#An Azure Logic Apps workflow started by a Sentinel trigger\nUsed for enrichment, sync, notification and response",s:"Logic Apps workflow for response automation",
  x:"A playbook is a Logic App whose first step is a Microsoft Sentinel trigger. Its steps can query threat intelligence, open tickets, post to Teams, isolate a device through Defender for Endpoint, or block a user in Entra ID, then write results back as comments or incident updates. Playbooks are billed as Logic Apps resources separately from Sentinel. Stem signal: anything that must talk to an external system or take a response action."},
 {c:"sentauto",obj:"1.1.11",q:"Playbook trigger: Microsoft Sentinel incident",a:"#Passes the whole incident: properties, alerts array, entities array\nThe trigger automation rules can call on incident events",s:"Receives the incident with its alerts and entities",g:"pbtrig",
  x:"The incident trigger is the recommended starting point. The playbook receives the incident's properties plus arrays of alerts and entities, and the designer auto-creates loops when you reference them. Only incident-trigger playbooks can be attached to incident-trigger automation rules or run from the incident page. Stem signal: 'the playbook must update the incident and read all entities'."},
 {c:"sentauto",obj:"1.1.11",q:"Playbook trigger: Microsoft Sentinel alert",a:"#Passes a single alert object\nFor rules without incidents; cannot react to Microsoft security rules",s:"Receives one alert; works without incidents",g:"pbtrig",
  x:"The alert trigger starts a playbook per alert from Scheduled or NRT analytics rules and is used when incident creation is disabled or when alerts are processed before grouping. It cannot automate responses to Microsoft security analytics rules and can be invoked only by alert-trigger automation rules or manual runs on an alert. Use the 'Alert - Get incident' action if you later need the incident."},
 {c:"sentauto",obj:"1.1.11",q:"Playbook trigger: Microsoft Sentinel entity",a:"#Passes one entity (account, host, IP, URL, file hash…)\nRun manually from an entity page or incident; not callable by automation rules",s:"Receives a single entity for on-demand actions",g:"pbtrig",
  x:"Entity-trigger playbooks act on one entity at a time, for example reset a user's password or block an IP, and are launched manually by an analyst from the entity within an incident or from the entity page. Automation rules cannot call them. Stem signal: 'analysts should be able to pick a user in an incident and run the containment playbook on just that account'.",
  w:"Entity trigger = manual, per-object; never from an automation rule."},
 {c:"sentauto",obj:"1.1.11",q:"Consumption vs Standard Logic Apps for playbooks",a:"#Consumption: multitenant, pay per run, template gallery supported\nStandard: single-tenant, fixed price, VNet, many workflows per app; no playbook templates",s:"Consumption = per-run and templates; Standard = dedicated",g:"laplan",
  x:"Both plans can host playbooks. Consumption runs on shared infrastructure, charges per action, and is what the Sentinel playbook templates deploy. Standard runs single-tenant with predictable pricing, private networking, CI/CD and multiple workflows in one app, but only stateful workflows are supported in Sentinel, templates are not, and private-endpoint apps need an access restriction policy. Stem signal: 'the playbook must reach resources inside a virtual network' points to Standard."},
 {c:"sentauto",obj:"1.1.11",q:"Playbook authentication to Sentinel — managed identity",a:"#System-assigned identity on the Logic App, granted a Sentinel role\nAvoids stored credentials; alternative: service principal or user",s:"Logic App identity holds a Sentinel role",
  x:"The Sentinel connector inside a playbook must authenticate to update incidents. The recommended approach is a managed identity on the Logic App that is assigned a role such as Microsoft Sentinel Responder on the workspace, so no secret is stored. A service principal with a secret or a signed-in user account are alternatives. Stem signal: 'the playbook must update incidents without storing credentials'."},
 {c:"sentauto",obj:"1.1.11",q:"Role to run a playbook manually",a:"#Microsoft Sentinel Playbook Operator\nPlus Responder (or higher) to open the incident",s:"Playbook Operator lists, views and runs playbooks",
  x:"Running a playbook on demand from an incident, alert or entity needs the Microsoft Sentinel Playbook Operator role on the playbook's resource group, and the analyst still needs at least Responder to reach the incident. Editing the Logic App itself requires Logic App Contributor instead. The exam separates these three: operate the playbook, edit the playbook, let Sentinel automate the playbook."},
 {c:"sentauto",obj:"1.1.11",q:"Role to create or edit a playbook",a:"#Logic App Contributor (Consumption) on the resource group\nStandard uses Logic Apps Standard Developer/Contributor roles",s:"Logic App Contributor edits the workflow",
  x:"Designing or changing a playbook is a Logic Apps task, so the author needs Logic App Contributor on the resource group for Consumption apps, or the Logic Apps Standard Developer or Contributor roles for Standard apps. Attaching a playbook to an analytics or automation rule additionally needs Microsoft Sentinel Contributor. Stem signal: 'can run playbooks but cannot modify them' describes Playbook Operator without Logic App Contributor."},
 {c:"sentauto",obj:"1.1.11",q:"Playbook templates — where they come from",a:"#Content hub solutions and the Automation page's Playbook templates tab\nDeploy, customize, then attach to rules",s:"Prebuilt Logic Apps from content hub",
  x:"Microsoft and partners publish ready-made playbooks as part of content hub solutions, visible on the Automation page under Playbook templates. Deploying a template creates a Consumption Logic App you then authorize and customize. Standard apps are not provisioned from templates. Stem signal: 'use a prebuilt playbook to post incidents to Teams' means install the solution and deploy its template."},
 {c:"sentauto",obj:"1.1.11",q:"Running a playbook from an incident manually",a:"#Incident > Actions > Run playbook (incident-trigger playbooks only)\nEntity playbooks run from the entity in the incident",s:"On-demand run from the incident's action menu",
  x:"An analyst can start an incident-trigger playbook from the incident page without any automation rule, which is useful for one-off enrichment or containment. The list shows only playbooks with the matching trigger, and the user needs Playbook Operator plus Sentinel permission to run on their behalf. Stem signal: 'allow analysts to decide per incident whether to isolate the device' is a manual run, not an automation rule.",
  w:"Manual run shows only playbooks whose trigger matches the object."},
 {c:"sentauto",obj:"1.1.11",q:"Playbook timing inside an automation rule",a:"#Rule waits up to 2 minutes for the playbook before moving on\nLong playbooks keep running, but later actions no longer wait",s:"Two-minute wait, then the rule continues",
  x:"When an automation rule runs a playbook, it pauses for the result up to about two minutes; if the playbook finishes sooner the rule proceeds immediately, and if it runs longer the rule continues with its next action while the playbook completes in the background. This matters when a later action depends on something the playbook writes, so order short enrichment playbooks before dependent actions."},
 /* ---------- sentplat: Sentinel platform — roles, retention, workbooks, SOC optimization ---------- */
 {c:"sentplat",obj:"1.2.1",q:"Microsoft Sentinel Reader",a:"#View data, incidents, workbooks and recommendations\nNo changes to incidents or content",s:"Read-only view of incidents and data",g:"sentrole",
  x:"Reader is the least-privileged Sentinel role: it can open incidents, run queries over workspace data, view workbooks and SOC optimization recommendations, but cannot assign, close or comment on incidents or create rules. It is the right answer for auditors, managers and dashboards. Stem signal: 'must be able to view but not modify incidents'."},
 {c:"sentplat",obj:"1.2.1",q:"Microsoft Sentinel Responder",a:"#Everything Reader has, plus managing incidents\nAssign, change status, add comments; no rule or content changes",s:"Manages incidents but cannot create rules",g:"sentrole",
  x:"Responder is the analyst role: it adds incident management — assignment, status and severity changes, comments, classification — on top of read access, but cannot create or edit analytics rules, workbooks, connectors or automation. Guest users also need Directory Reader in Entra ID to be assignable. Stem signal: 'triage and close incidents without being able to change detections'.",
  w:"Responder responds; Contributor builds."},
 {c:"sentplat",obj:"1.2.1",q:"Microsoft Sentinel Contributor",a:"#Responder rights plus create/edit rules, workbooks, connectors, content hub\nCannot run or edit playbooks on its own",s:"Builds detections and content, manages content hub",g:"sentrole",
  x:"Contributor is the engineering role: it installs solutions from the content hub, enables data connectors, creates analytics and automation rules, and attaches playbooks to rules. It does not by itself grant permission to execute or author Logic Apps, which need Playbook Operator or Logic App Contributor, and creating workbooks also needs Workbook Contributor on the resource group. Stem signal: 'create analytics rules' is at least Contributor."},
 {c:"sentplat",obj:"1.2.1",q:"Microsoft Sentinel Playbook Operator",a:"#List, view and run playbooks manually\nNo editing of the Logic App",s:"Runs playbooks on demand only",g:"sentrole",
  x:"Playbook Operator exists so analysts can trigger response playbooks from an incident without being able to change them. Pair it with Responder for day-to-day SOC work. It does not let Sentinel run playbooks automatically — that is the Automation Contributor role on the service identity — and it does not permit designing workflows. Stem signal: 'run but not modify playbooks'."},
 {c:"sentplat",obj:"1.2.1",q:"Microsoft Sentinel Automation Contributor",a:"#Lets the Sentinel service identity attach and run playbooks in automation rules\nAssigned on the playbook resource group, never to people",s:"Service-only role so Sentinel can run playbooks",g:"sentrole",
  x:"Automation Contributor is granted to Sentinel's own identity on the resource group that holds playbooks, through the Manage playbook permissions pane. It is not meant for users. Without it, automation rules that include a Run playbook action fail even though analysts can run the same playbook manually. Stem signal: 'the automation rule's playbook action never executes'."},
 {c:"sentplat",obj:"1.2.1",q:"Log Analytics roles that matter for Sentinel",a:"#Log Analytics Reader: query the workspace\nLog Analytics Contributor: manage tables, retention, DCR links",s:"Reader queries; Contributor changes workspace settings",
  x:"Sentinel roles sit on top of Azure Monitor roles. Log Analytics Reader allows querying the workspace from Logs without any Sentinel UI rights; Log Analytics Contributor allows changing workspace configuration such as table plans, retention, custom tables and agent settings, which Sentinel Contributor alone does not include. Stem signal: 'change the retention of a table' needs a Log Analytics or workspace-level contributor role."},
 {c:"sentplat",obj:"1.2.1",q:"Roles needed to create and delete workbooks",a:"#Microsoft Sentinel Contributor plus Workbook Contributor\nViewing needs Workbook Reader",s:"Sentinel Contributor + Workbook Contributor",
  x:"Workbooks are Azure resources in the workspace's resource group, so saving or deleting one requires Workbook Contributor there in addition to Sentinel Contributor; Workbook Reader is enough to open saved workbooks. The exam uses this to test that Sentinel roles do not automatically carry every Azure resource permission. Stem signal: 'can view workbooks but cannot save changes'."},
 {c:"sentplat",obj:"1.2.2",q:"Analytics retention vs total retention",a:"#Analytics (interactive): hot, queryable, 30 days to 2 years\nTotal: up to 12 years; the difference is long-term (data lake) retention",s:"Interactive window inside a longer total window",g:"rettier",
  x:"Every table has two numbers. Analytics retention is how long data stays in the hot analytics tier for real-time queries, alerting and hunting. Total retention is how long it exists at all, with the remainder beyond the analytics window held cheaply in the data lake. Setting analytics 90 and total 365 gives 90 hot days and 275 lake days. Stem signal: 'retain for seven years for compliance but only search interactively for 90 days'.",
  w:"Analytics = hot window; total = everything, lake fills the gap."},
 {c:"sentplat",obj:"1.2.2",q:"Analytics tier — what it supports",a:"#Analytics rules, hunting, workbooks, watchlists, search and summary rules\nDefault 30 days; Sentinel solution tables free to 90 days",s:"Hot tier that powers rules, hunting and workbooks",g:"rettier",
  x:"The analytics tier is the classic Log Analytics tier for Sentinel: full KQL, scheduled and NRT rules, workbooks, watchlists, parsers, restore and export all work here. Retention defaults to 30 days and can be raised to two years at a prorated charge, with many Sentinel solution tables eligible for 90 days at no extra cost. Any detection requirement in a stem implies the data must be in this tier."},
 {c:"sentplat",obj:"1.2.2",q:"Data lake tier — what it supports",a:"#Long-term storage up to 12 years; KQL jobs, notebooks, search, summary rules\nNo real-time analytics rules or hunting",s:"Cold tier for jobs and notebooks, no live rules",g:"rettier",
  x:"The data lake tier stores data cheaply for as long as twelve years and is queried through scheduled or one-time KQL jobs, Spark notebooks and search jobs, with results promotable back to the analytics tier. Moving a table to lake-only stops alerting, advanced hunting, analytics rules and custom detections on it. Stem signal: 'keep firewall logs for six years at minimum cost; they are rarely queried'."},
 {c:"sentplat",obj:"1.2.2",q:"Defender XDR default retention in the Defender portal",a:"#30 days of advanced hunting data included in the XDR license\nExtend by ingesting the tables into the analytics or data lake tier",s:"30 days free in XDR; longer means Sentinel tiers",g:"rettier",
  x:"Defender XDR advanced hunting tables such as DeviceProcessEvents are kept for 30 days by default with no ingestion charge. On the Tables page you can extend a table into the analytics tier (31 to 90 days are storage-free though ingestion is billed) or into the data lake for up to twelve years. Stem signal: 'hunt across six months of endpoint process events' cannot be met with the XDR default alone.",
  w:"XDR gives 30 days; Sentinel tiers buy the rest."},
 {c:"sentplat",obj:"1.2.2",q:"Where do you change a table's tier and retention?",a:"#Defender portal: Microsoft Sentinel > Configuration > Tables\nAnalytics tier or Data lake tier, with retention values per table",s:"Sentinel Configuration > Tables page",
  x:"Table-level settings live on the Tables page under Sentinel configuration in the Defender portal. For each table you pick the tier and set analytics retention (30 days to 2 years) and total retention (up to 12 years), or choose Data lake tier only. Some XDR and solution tables must remain analytics-tier because Microsoft services depend on them. Shortening retention gives a 30-day grace period before data is deleted."},
 {c:"sentplat",obj:"1.2.2",q:"Mirroring from the analytics tier to the data lake",a:"#Analytics-tier data is automatically copied to the lake for the same retention\nExtra lake retention beyond that is billed as storage",s:"Hot data is mirrored to the lake at no extra ingestion cost",
  x:"Everything ingested into the analytics tier is mirrored into the data lake, so jobs and notebooks can read the same data without a second ingestion. Extending total retention beyond the analytics window costs only lake storage. This single-copy model is why the exam calls the lake 'cost-effective long-term retention' rather than an archive you must export to."},
 {c:"sentplat",obj:"1.2.2",q:"Legacy table plans: Analytics, Basic, Auxiliary",a:"#Analytics: full features; Basic: cheap ingestion, 30-day fixed interactive; Auxiliary: lowest cost\nBasic and Auxiliary map onto the data lake model",s:"Three Log Analytics plans; cheaper plans map to the lake",
  x:"Log Analytics offers three plans. Analytics is full-featured with 4 to 730 days interactive retention. Basic has a fixed 30-day interactive window and limited KQL, with total retention up to twelve years via search jobs. Auxiliary is the cheapest, with no interactive window but queryable across its retention. In the Defender portal these lower-cost plans surface as the data lake tier. Stem signal: 'reduce ingestion cost for verbose logs' means Basic/Auxiliary or lake."},
 {c:"sentplat",obj:"1.2.3",q:"Sentinel workbooks — what they are",a:"#Interactive KQL-driven dashboards built on Azure Monitor workbooks\nSaved as JSON resources in the workspace resource group",s:"Interactive dashboards over workspace data",
  x:"Workbooks render KQL results as tables, charts, tiles and grids with parameters and time-range controls, and support auto-refresh from five minutes to a day. Each saved workbook is an Azure resource stored as JSON next to the workspace, visible in both the Defender portal and, until retirement, the Azure portal. Stem signal: 'visualize sign-in failures by country for the SOC lead' is a workbook, not an analytics rule."},
 {c:"sentplat",obj:"1.2.3",q:"Workbook templates vs saved workbooks",a:"#Templates tab: from content hub, cannot be deleted\nMy workbooks tab: saved copies you can edit and delete",s:"Templates are read-only; saved copies are yours",
  x:"Installing a solution from the content hub adds workbook templates. Opening a template and saving it creates a workbook in My workbooks that you own, can customize and can delete; the template itself stays untouched. Templates list the data types they need, so check the connector is streaming before relying on one. Stem signal: 'the workbook shows no data' usually means the required table is empty.",
  w:"Template = blueprint; saved = your copy."},
 {c:"sentplat",obj:"1.2.3",q:"Workbook parameters and time range",a:"#Parameters drive queries (time range, workspace, drop-downs)\nTime range picker filters every query that references it",s:"User-set inputs that queries reference",
  x:"Parameters make one workbook serve many questions: a time range parameter feeds every query, a drop-down of hosts or users filters sections, and a workspace parameter lets the same workbook span several workspaces. Queries reference parameters by name inside braces. Stem signal: 'let analysts choose the time window and the device group without editing the query'."},
 {c:"sentplat",obj:"1.2.3",q:"Workbook queries — ASIM recommendation",a:"#Prefer ASIM parsers over raw tables for multi-source visuals\nOne workbook then covers any normalized source",s:"Normalized parsers keep workbooks source-agnostic",
  x:"Microsoft recommends building workbook queries on Advanced Security Information Model parsers such as imNetworkSession rather than vendor-specific tables, so adding a new firewall does not require rewriting the dashboard. The same advice applies to analytics rules. Stem signal: 'a single network workbook for Palo Alto, Fortinet and Azure Firewall data'."},
 {c:"sentplat",obj:"1.2.4",q:"SOC optimization — the two recommendation families",a:"#Coverage: threat-based, AI MITRE ATT&CK, risk-based gaps\nData value: unused or low-value ingestion and better plans",s:"Coverage gaps and data-value recommendations",
  x:"SOC optimization analyzes the workspace daily and produces recommendations in two groups. Coverage recommendations point out detections you could enable for specific threats, MITRE techniques or business risks. Data value recommendations highlight tables you pay to ingest but never query or detect on, and suggest cheaper plans or useful content for them. Stem signal: 'reduce cost of unused logs' is data value; 'close ransomware detection gaps' is coverage.",
  w:"Coverage = detect more; data value = pay less."},
 {c:"sentplat",obj:"1.2.4",q:"SOC optimization — statuses and refresh",a:"#Active, In progress, Completed, Dismissed\nRecalculated every 24 hours",s:"Active, in progress, completed or dismissed",
  x:"Each recommendation starts Active, can be marked In progress while a team works on it, becomes Completed when its actions are done (or automatically when the environment changes), and can be Dismissed to hide it. The engine recomputes every day, and reactivated items take up to an hour to refresh. The page lives under SOC optimization in the Defender portal and shows coverage percentages and 90-day ingestion."},
 {c:"sentplat",obj:"1.2.4",q:"Workspace manager — central content distribution",a:"#Publish analytics rules, automation rules, hunting queries, workbooks, parsers to member workspaces\nNeeds Contributor on central and member; playbooks excluded",s:"Push content from one workspace to many",
  x:"Workspace manager turns one workspace into a central publisher that pushes read-only copies of content to member workspaces, grouped by business logic, including across tenants through Azure Lighthouse. Supported content covers analytics and automation rules, saved searches and parsers, hunting queries and workbooks, but not playbooks. Stem signal: an MSSP or multi-region enterprise that must keep detections consistent across many workspaces.",
  w:"Workspace manager publishes rules, not playbooks."},
 {c:"sentplat",obj:"1.2.4",q:"Unified SecOps: Sentinel in the Defender portal",a:"#Onboard a workspace to get one incident queue, cross-domain correlation, unified hunting\nAzure portal access ends after 31 March 2027",s:"Sentinel operated inside the Defender portal",
  x:"Onboarding a Sentinel workspace to the Defender portal merges SIEM incidents with Defender XDR incidents, applies XDR correlation and attack-story views, and exposes one advanced hunting experience across SIEM, XDR and lake data. Only the primary workspace is correlated with Defender alerts; secondary workspaces keep separate incident creation. Fusion and Microsoft incident creation rules are not used once onboarded. Stem signal: 'single queue for Sentinel and Defender incidents'."},
 /* ---------- ingest: connectors, AMA, DCR, WEF, Syslog/CEF, TI, custom tables ---------- */
 {c:"ingest",obj:"1.3.1",q:"Service-to-service (native) connectors",a:"#Microsoft or cloud services stream directly into the workspace\nExamples: Defender XDR, Microsoft 365, Azure Activity, Entra ID, AWS S3",s:"Direct cloud-to-workspace streaming, no agent",g:"conntype",
  x:"Native connectors use the source service's own export path, often a diagnostic setting or an API Microsoft operates, so there is nothing to install. Configuration is mostly permissions and ticking which log types to send. The exam expects you to pick these for Microsoft sources and to know the table each lands in, for example OfficeActivity for Microsoft 365 and SigninLogs for Entra ID."},
 {c:"ingest",obj:"1.3.1",q:"Agent-based connectors via Azure Monitor Agent",a:"#AMA on the machine or log forwarder, governed by a DCR\nWindows Security Events, Windows Forwarded Events, Syslog, CEF, custom text logs",s:"AMA plus DCR collects from servers and forwarders",g:"conntype",
  x:"When the data lives on a machine — Windows event logs, Linux syslog, a CEF stream from appliances, or a text file — the Azure Monitor Agent collects it according to a data collection rule that says what to gather and which workspace receives it. Non-Azure machines must be Azure Arc-enabled so the DCR can target them. Stem signal: 'on-premises servers', 'firewall logs', 'install an agent'.",
  w:"On a box? AMA + DCR. In a cloud service? Native connector."},
 {c:"ingest",obj:"1.3.1",q:"Codeless Connector Framework (CCF) connectors",a:"#Microsoft-hosted polling or push connectors for SaaS APIs\nNo Function App or agent to maintain",s:"Hosted API connectors with nothing to deploy",g:"conntype",
  x:"CCF connectors are defined declaratively and run inside Sentinel, either polling a vendor's REST API on a schedule or accepting pushed events through a data collection endpoint. They replace many older Azure Functions connectors and cost nothing extra to host. Stem signal: 'ingest from a SaaS platform's API without deploying Azure resources' points to CCF where one exists."},
 {c:"ingest",obj:"1.3.1",q:"Azure Functions-based connectors",a:"#A Function App you deploy polls the vendor API and writes to a _CL table\nCustomer pays for and maintains the Function App",s:"Self-hosted Function App polling an API",g:"conntype",
  x:"Some third-party connectors deploy an Azure Function App into your subscription that calls the vendor's API on a timer and posts results to a custom table through the ingestion API. You own the credentials, scaling and cost. Compared with CCF, this is the heavier option; the exam may ask which connector type incurs extra Azure resource charges, and this is it."},
 {c:"ingest",obj:"1.3.1",q:"Which Windows connector for domain controllers' security events?",a:"#Windows Security Events via AMA → SecurityEvent table\nFiltered by DCR; built-in rules target SecurityEvent",s:"Security Events via AMA into SecurityEvent",
  x:"For member servers and domain controllers you can reach with an agent, Windows Security Events via AMA is the primary connector: install AMA (Arc for on-prem), create a DCR with an event filter, and data lands in SecurityEvent where the built-in analytics rules expect it. Choose Windows Forwarded Events only when events are already centralized with WEF. Stem signal: 'use existing analytics rule templates for Windows security events'."},
 {c:"ingest",obj:"1.3.2",q:"Data collection rule (DCR) — what it defines",a:"#What AMA collects (event filters) and where it lands (workspace, table)\nReusable across many machines; attached to resources",s:"Collection scope and destination for AMA",
  x:"A DCR is the configuration object the Azure Monitor Agent downloads: data sources, filters such as XPath for Windows events or facilities for syslog, optional transformations, and the destination workspace. One rule can be associated with hundreds of machines, which is why filtering at the source in the DCR is the cost lever the exam highlights. Stem signal: 'collect only events 4624 and 4688 from the servers'."},
 {c:"ingest",obj:"1.3.2",q:"Security event collection levels in the DCR",a:"#All security events, Common, Minimal, Custom\nCustom uses XPath queries",s:"All, Common, Minimal, or Custom XPath",g:"seclevel",
  x:"The Windows Security Events via AMA connector offers four presets. All events collects the full Security log. Common is the standard set for typical SOC monitoring. Minimal keeps only a small essential set to save cost. Custom lets you write XPath expressions for exactly the IDs you need, up to 20 expressions per box. Stem signal: a cost or specific-event-ID requirement decides between Minimal and Custom."},
 {c:"ingest",obj:"1.3.2",q:"XPath filter for a DCR — the shape",a:"#Channel!*[System[(EventID=4624) or (EventID=4688)]]\nTest locally with Get-WinEvent -FilterXPath",s:"Event log channel plus System[EventID] predicates",k:"Security!*[System[(EventID=4624) or (EventID=4688)]]\n\nGet-WinEvent -LogName Security -FilterXPath '*[System[EventID=4688]]' -MaxEvents 5",
  x:"A custom DCR filter names the channel, then an XPath predicate on the event's System properties, most often EventID, joined with or. Because a bad expression silently collects nothing, Microsoft suggests validating the predicate on a machine with Get-WinEvent before saving. Exam stems may show an XPath string and ask which events it collects, or ask you to pick the expression that limits ingestion to specific IDs."},
 {c:"ingest",obj:"1.3.2",q:"Prerequisites to target a non-Azure server with a DCR",a:"#Azure Arc Connected Machine agent on the server\nThen AMA is deployed and the DCR associated",s:"Azure Arc enrollment before AMA and DCR",
  x:"DCRs are associated with Azure resources, so a physical or on-premises server must first be projected into Azure through Azure Arc. Once Arc-enabled, it appears in the connector's Resources picker, AMA is installed as an extension, and the DCR applies. Stem signal: 'the on-premises server does not appear when selecting resources for the data collection rule' — it is not Arc-enabled.",
  w:"Not in Azure? Arc first, then AMA."},
 {c:"ingest",obj:"1.3.3",q:"Windows Event Forwarding (WEF) — the model",a:"#Source computers forward events to a Windows Event Collector server\nEvents land in the collector's ForwardedEvents log",s:"Centralize events on a collector before shipping",
  x:"WEF uses built-in Windows subscriptions so that many machines push or are pulled for events to one or more collector servers, where they arrive in the ForwardedEvents channel. Only the collector needs the Azure Monitor Agent. It suits environments where installing an agent on every host is impractical or where a collector tier already exists. Stem signal: 'minimize agents' or 'existing event collector'."},
 {c:"ingest",obj:"1.3.3",q:"Windows Forwarded Events connector — the table",a:"#AMA on the collector reads ForwardedEvents into WindowsEvent\nNot SecurityEvent, so built-in rules need adapting or ASIM parsers",s:"Collector events land in WindowsEvent",
  x:"The Windows Forwarded Events connector ingests the collector's ForwardedEvents channel through a DCR into the WindowsEvent table. Because most Microsoft analytics rule templates query SecurityEvent, you must either rewrite them for WindowsEvent, install ASIM parsers, or collect directly with Windows Security Events via AMA instead. Exam stems that pair WEF with 'built-in rules do not fire' are testing exactly this table mismatch.",
  w:"WEF → WindowsEvent; direct AMA → SecurityEvent."},
 {c:"ingest",obj:"1.3.3",q:"When to prefer WEF over per-host AMA",a:"#Many hosts, agent restrictions, or an existing collector tier\nTrade-off: single table change and one extra hop",s:"Fewer agents at the cost of WindowsEvent compatibility",
  x:"Planning questions compare the two Windows paths. Per-host AMA gives SecurityEvent compatibility and per-machine DCR filtering but requires an agent (and Arc) on every server. WEF concentrates collection on a few collectors, reduces agents and works well with existing Windows subscriptions, but delivers into WindowsEvent and adds the collector as a dependency. Pick based on the stem's constraints about agents and rule reuse."},
 {c:"ingest",obj:"1.3.4",q:"Syslog via AMA — the pipeline",a:"#Devices → Linux log forwarder (rsyslog/syslog-ng) on port 514 → AMA → Syslog table\nDCR selects facilities and minimum level",s:"Forwarder listens on 514, AMA ships to Syslog table",g:"linuxconn",
  x:"Syslog via AMA collects standard syslog from Linux hosts and network devices. A designated Linux VM runs rsyslog or syslog-ng listening on TCP/UDP 514, the AMA on that VM applies a DCR that chooses facilities (such as local0–local7, auth) and the lowest severity to keep, and records arrive in the Syslog table. Non-Azure forwarders need Azure Arc. Stem signal: 'collect auth logs from Linux servers'."},
 {c:"ingest",obj:"1.3.4",q:"CEF via AMA — the pipeline",a:"#Appliances send CEF over syslog → forwarder on 514 → AMA → CommonSecurityLog\nSame forwarder VM can carry both, with distinct facilities",s:"CEF messages parsed into CommonSecurityLog",g:"linuxconn",
  x:"Common Event Format is a structured key-value syslog payload used by firewalls, proxies and security appliances. CEF via AMA uses the same Linux forwarder and port 514 but parses messages into the CommonSecurityLog table with DeviceVendor, DeviceProduct and typed fields. The forwarder is prepared with the Forwarder_AMA_installer.py script. Stem signal: 'Palo Alto', 'Fortinet' or 'CEF' in the scenario.",
  w:"CEF → CommonSecurityLog; plain syslog → Syslog."},
 {c:"ingest",obj:"1.3.4",q:"Avoiding duplicate ingestion with Syslog and CEF on one forwarder",a:"#Use different facilities for CEF and for plain syslog in the two DCRs\nSame facility in both = every message ingested twice",s:"Separate facilities per DCR to prevent duplicates",
  x:"Because both connectors read the same rsyslog stream on one forwarder, a facility selected in the CEF DCR and also in the Syslog DCR causes each message to be stored in both CommonSecurityLog and Syslog, doubling cost. The fix is to send CEF sources to a dedicated facility (for example local4) and exclude it from the Syslog DCR. Stem signal: 'firewall events appear in two tables'."},
 {c:"ingest",obj:"1.3.4",q:"Syslog DCR minimum log level — how it filters",a:"#Choosing a level keeps that level and everything more severe\nLOG_ERR keeps ERR, CRIT, ALERT, EMERG",s:"Selected severity plus all higher severities",
  x:"For each facility in a Syslog DCR you choose the minimum severity. Syslog severities run from debug up to emergency; picking Error collects Error, Critical, Alert and Emergency but drops Warning, Notice, Info and Debug. This is the main cost control for chatty Linux hosts. Stem signal: 'reduce syslog volume but keep anything that indicates a failure'."},
 {c:"ingest",obj:"1.3.5",q:"Azure Activity connector — how it is wired today",a:"#Azure Policy assigns a subscription-scope diagnostic setting\nPolicy: Configure Azure Activity logs to stream to specified Log Analytics workspace",s:"Policy-deployed diagnostic setting per subscription",
  x:"The current Azure Activity connector uses an Azure Policy definition that creates a diagnostic setting on each subscription in scope to stream the activity log into the workspace's AzureActivity table. Assign the policy at a management group or subscription, then run a remediation task so existing subscriptions are configured. The old per-subscription legacy method is retired. Stem signal: 'ensure all current and future subscriptions send activity logs'.",
  w:"Activity logs scale with Policy, not clicks."},
 {c:"ingest",obj:"1.3.5",q:"Remediation task — why it is needed with the Activity policy",a:"#Policy only auto-applies to new or changed resources\nRemediation configures the subscriptions that already exist",s:"Applies the policy to existing subscriptions",
  x:"A deployIfNotExists policy evaluates resources at creation or update, so subscriptions that existed before the assignment stay non-compliant until a remediation task runs and deploys the diagnostic setting. Forgetting the task is the classic reason 'the AzureActivity table is empty for older subscriptions' in exam scenarios."},
 {c:"ingest",obj:"1.3.5",q:"Resource diagnostic settings for Azure services",a:"#Per-resource setting that sends logs/metrics to a workspace\nKey Vault, NSG flow, Firewall, SQL etc. use their own tables",s:"Per-resource log export into the workspace",
  x:"Beyond subscription activity, individual Azure resources such as Key Vault, Azure Firewall or Azure SQL emit resource logs selected in that resource's Diagnostic settings blade and routed to Log Analytics, each into a resource-specific table. Sentinel's Azure connectors in the content hub mostly wrap these settings, and Azure Policy can enforce them at scale. Stem signal: 'collect audit logs from Key Vault' is a diagnostic setting, not an agent."},
 {c:"ingest",obj:"1.3.5",q:"Microsoft Entra ID connector — log types and tables",a:"#Sign-in → SigninLogs, Audit → AuditLogs, non-interactive → AADNonInteractiveUserSignInLogs\nAlso service principal, managed identity, provisioning, risk logs",s:"Entra diagnostic setting into SigninLogs, AuditLogs and more",
  x:"The Entra ID connector creates a tenant-level diagnostic setting and lets you tick each log category. Interactive sign-ins populate SigninLogs, directory changes populate AuditLogs, and separate tables hold non-interactive, service principal, managed identity and AD FS sign-ins plus provisioning and ID Protection risk logs. Sign-in logs need a P1 or P2 license. Stem signal: 'detect legacy authentication' is SigninLogs; 'who added a global admin' is AuditLogs.",
  w:"Sign-in = who logged on; Audit = who changed the directory."},
 {c:"ingest",obj:"1.3.6",q:"Threat intelligence upload API",a:"#Recommended path: push STIX objects straight to the workspace\nNo connector needed; app registration with workspace-scoped permission",s:"Push STIX objects via REST without a connector",g:"ticonn",
  x:"The upload API accepts STIX 2.1 objects — indicators, threat actors, attack patterns, identities, relationships — from a threat intelligence platform or script and writes them into the workspace. It replaces the deprecated Graph tiIndicators-based Threat Intelligence Platforms connector and supports more than plain indicators. Stem signal: 'integrate our TIP' or 'import indicators from a custom feed programmatically'."},
 {c:"ingest",obj:"1.3.6",q:"Threat Intelligence – TAXII connector",a:"#Built-in TAXII 2.0/2.1 client polls a server's collection\nNeeds API root URL and collection ID",s:"Pulls STIX from a TAXII server collection",g:"ticonn",
  x:"For feeds published over the TAXII protocol, this connector lets Sentinel act as the client: supply the server's API root, the collection ID, credentials and a polling interval, and indicators flow in on schedule. Stem signal: 'the ISAC publishes indicators via TAXII'. Compare with the upload API, where your system pushes, and with the Defender Threat Intelligence connector, which brings Microsoft's own feed."},
 {c:"ingest",obj:"1.3.6",q:"Microsoft Defender Threat Intelligence connector",a:"#Brings Microsoft's indicator feed into the workspace\nStandard (open-source and public IOCs) vs Premium (Microsoft IOCs)",s:"Microsoft's own TI feed, standard or premium",g:"ticonn",
  x:"This connector streams indicators curated by Microsoft Defender Threat Intelligence into the workspace with a single enable. The standard version supplies public and OSINT indicators free; the premium version adds Microsoft-sourced and enriched indicators under a license. It pairs with the Threat Intelligence analytics rule and the TI workbook. Stem signal: 'use Microsoft-provided indicators without running our own feed'."},
 {c:"ingest",obj:"1.3.6",q:"Threat intelligence tables — new vs legacy",a:"#ThreatIntelIndicators and ThreatIntelObjects (STIX schema)\nThreatIntelligenceIndicator is legacy and retired",s:"ThreatIntelIndicators/Objects replace the old table",
  x:"Sentinel moved threat intelligence storage to two STIX-shaped tables: ThreatIntelIndicators for indicators and ThreatIntelObjects for actors, attack patterns, identities and relationships. The older ThreatIntelligenceIndicator table was deprecated in 2025, so rules, workbooks and queries must reference the new tables. Exam stems that still mention the legacy table are testing whether you know the migration.",
  w:"Plural + Objects = current; singular = legacy."},
 {c:"ingest",obj:"1.3.6",q:"TI ingestion rules",a:"#Filter or modify indicators before storage: drop low confidence, extend validity, tag\nApply to connector-ingested TI; take ~15 minutes",s:"Pre-storage filters and edits for incoming indicators",
  x:"Ingestion rules run on indicators arriving through connectors and let you discard stale or low-confidence entries, extend expiry on trusted sources, or add tags that match your naming scheme. Rules evaluate in order until a delete action. They are managed in the Intel management area of the Defender portal. Stem signal: 'reduce false positives from a noisy feed before indicators reach matching rules'."},
 {c:"ingest",obj:"1.3.7",q:"Custom log tables — the _CL suffix",a:"#Every custom table name ends in _CL (e.g. FabrikamApp_CL)\nPortal adds it; API/CLI must include it",s:"Custom tables are named with _CL",
  x:"Custom tables in Log Analytics are identified by the _CL suffix, which the portal appends automatically and which must be part of the stream name in a DCR when you create tables through the API. Avoid sensitive terms in names because table names appear in billing. Stem signal: a query against a table ending in _CL means custom-ingested data, often from a Function App or the ingestion API."},
 {c:"ingest",obj:"1.3.7",q:"Creating a DCR-based custom table in the portal",a:"#Workspace > Tables > Create > New custom log (DCR-based)\nPick plan, DCR and DCE, upload sample JSON, define transformation",s:"Tables page wizard with sample JSON and a DCR",
  x:"The modern custom-table wizard asks for a name and plan, a data collection rule and endpoint, then a JSON sample with at least one record so the schema can be inferred. You can add a KQL transformation before saving. The resulting table can be fed through the Logs ingestion API or AMA custom text logs. Stem signal: 'store JSON events from an in-house application in a dedicated table'."},
 {c:"ingest",obj:"1.3.7",q:"TimeGenerated requirement for custom tables",a:"#Every table must have a TimeGenerated datetime column\nTransformation can derive it if the source lacks one",s:"TimeGenerated column is mandatory",
  x:"Log Analytics indexes and retains data on TimeGenerated, so a custom table must include it. If the incoming records only have a field such as eventTime, the DCR transformation extends TimeGenerated from it, otherwise ingestion time is used. Exam stems that show a transformKql snippet with extend TimeGenerated are illustrating this requirement.",k:"source\n| extend TimeGenerated = todatetime(eventTime)\n| project-away eventTime"},
 {c:"ingest",obj:"1.3.7",q:"Logs ingestion API — prerequisites",a:"#DCE + DCR, an Entra app, and Monitoring Metrics Publisher on the DCR/DCE\nPOST JSON to the endpoint; DCR stream maps to table",s:"DCE, DCR, app registration with publisher role",
  x:"To push data from your own code, you register an Entra application, create a data collection endpoint and a DCR whose stream declaration matches your JSON, and grant the app the Monitoring Metrics Publisher role. Posts go to the DCE URL with the DCR immutable ID and stream name. Schema changes to the table must be mirrored in the DCR by hand. Stem signal: 'send events from a custom application to Sentinel securely'."},
 {c:"ingest",obj:"1.3.7",q:"DCR transformations — what they do",a:"#KQL applied to each record before it is stored\nFilter, drop columns, mask data, split to tables",s:"Ingestion-time KQL that reshapes or filters rows",
  x:"A transformation is a KQL statement over the pseudo-table source inside a DCR. It can drop noisy rows, remove or mask fields, parse strings into columns, or route data to a different table, all before billing for ingestion. Transformations apply to custom tables and to many standard tables via workspace DCRs. Stem signal: 'exclude informational events before ingestion' or 'remove personal data at collection time'.",k:"source\n| where Level != \"Information\"\n| project-away RawPayload"},
 {c:"ingest",obj:"1.3.1",q:"Defender XDR connector — incidents and raw events",a:"#Incidents/alerts synced bidirectionally into SecurityIncident/SecurityAlert\nOptional raw tables: Device*, Email*, Identity*, CloudApp*, Alert*",s:"Syncs XDR incidents and streams hunting tables",
  x:"The Defender XDR connector does two jobs: it mirrors Defender incidents and alerts into Sentinel with two-way status sync, and it can stream the advanced hunting event tables so you keep them longer and correlate in KQL. Connecting incidents disables the individual Defender product connectors and you should turn off their Microsoft incident creation rules to avoid duplicates. Vulnerability management tables are not included.",
  w:"XDR connector: one incident sync, many raw tables, no TVM."},
 {c:"ingest",obj:"1.3.1",q:"Microsoft 365 connector — the table",a:"#Exchange, SharePoint, Teams audit activity → OfficeActivity\nSelect each workload when enabling",s:"Microsoft 365 workload audit into OfficeActivity",
  x:"The Microsoft 365 (formerly Office 365) connector pulls unified audit records for Exchange Online, SharePoint and OneDrive, and Teams into the OfficeActivity table, with each workload chosen separately when you enable it. It is a service-to-service connector requiring tenant-level security admin permissions. Stem signal: 'detect mass file downloads from SharePoint' or 'mailbox forwarding rules' both start in OfficeActivity."},
 /* ---------- detect: custom detections, analytics rules, MITRE, anomalies ---------- */
 {c:"detect",obj:"1.4.1",q:"Custom detection rule — what it is",a:"#An advanced hunting query that runs on a schedule and raises alerts\nCan trigger response actions on devices, users, files, emails",s:"Scheduled hunting query that alerts and responds",
  x:"In Defender XDR you turn a working advanced hunting query into a custom detection by saving it with a frequency, alert details and optional automated actions. Each run that returns rows creates alerts and incidents just like built-in detections. Stem signal: 'alert whenever this KQL returns results in Defender' — not a Sentinel analytics rule, which is the equivalent on the SIEM side.",
  w:"Custom detection = hunting query with a schedule and a verdict."},
 {c:"detect",obj:"1.4.1",q:"Columns a custom detection query must return",a:"#Timestamp and ReportId, plus at least one entity column\nDefender for Endpoint tables: DeviceId and ReportId",s:"Timestamp, ReportId and an entity identifier",
  x:"The wizard rejects a query that lacks the columns it needs to anchor an alert: Timestamp (or TimeGenerated) for the alert time, ReportId to point at the triggering event, and an entity identifier such as DeviceId, AccountObjectId, AccountSid, RecipientEmailAddress or SenderFromAddress so impacted assets can be populated. Summarized queries typically keep them with arg_max. Stem signal: 'the query cannot be saved as a detection' with a project that dropped ReportId.",k:"DeviceProcessEvents\n| where FileName =~ \"mimikatz.exe\"\n| project Timestamp, ReportId, DeviceId, AccountName"},
 {c:"detect",obj:"1.4.1",q:"Custom detection frequency options",a:"#Every 24 hours, 12 hours, 3 hours, every hour, or Continuous (NRT)\nDefender lookback: 30d, 48h, 12h, 4h respectively",s:"24h, 12h, 3h, hourly, or continuous",g:"cdfreq",
  x:"When saving a detection you choose how often it runs; each interval has a matching lookback window over Defender data, from 30 days for a daily rule down to 4 hours for an hourly one. Continuous runs in near real time against data as it is ingested. Lookback longer than frequency can produce duplicate hits, which the engine de-duplicates by entities and details. Stem signal: 'detect within minutes' means Continuous."},
 {c:"detect",obj:"1.4.1",q:"Continuous (NRT) frequency — query constraints",a:"#Single table, supported operators only, no join/union/externaldata, no comments\nOnly certain tables such as DeviceEvents, EmailEvents, IdentityLogonEvents",s:"One supported table, no joins, no comments",g:"cdfreq",
  x:"Continuous custom detections run as the data streams in, so the query must be simple: one table from the supported list, only operators the streaming engine understands, and no join, union, externaldata or comment lines. If a stem shows a query with a join and asks why Continuous is unavailable, that is the reason; fall back to hourly.",k:"// not NRT-eligible: two tables\nDeviceProcessEvents\n| join kind=inner DeviceNetworkEvents on DeviceId"},
 {c:"detect",obj:"1.4.1",q:"Custom detection alert details",a:"#Title, severity, category, MITRE techniques, description, recommended actions\nTitle/description can embed columns with {{ColumnName}}",s:"Title, severity, category, technique, actions",
  x:"Every custom detection carries the metadata the SOC sees on the alert: a unique title that may include dynamic column values, a severity, a category such as Credential access, mapped ATT&CK techniques, a description and recommended actions, plus up to 20 custom details. These fields also flow into Sentinel if the XDR connector is on. Stem signal: 'the alert title must show the user name' means a dynamic title."},
 {c:"detect",obj:"1.4.1",q:"Custom detection automated actions",a:"#Devices: isolate, collect package, AV scan, investigate, restrict apps\nUsers: mark compromised, disable, reset password; emails: move or delete; files: allow/block, quarantine",s:"Device, user, file and email responses per hit",
  x:"Response actions attach to the entity columns the query returns: device actions need DeviceId, user actions need an account identifier, email actions need NetworkMessageId and RecipientEmailAddress, file actions need a hash. Actions run automatically each time the rule fires, so test scope carefully. Stem signal: 'automatically isolate any device that runs this binary' is a custom detection with Isolate device."},
 {c:"detect",obj:"1.4.2",q:"Managing custom detection rules",a:"#Custom detection rules page: edit, turn on/off, run now, delete, view triggered alerts\nNeeds Manage security settings (Security Administrator)",s:"Edit, toggle, run, delete from the rules page",
  x:"The Custom detection rules page lists every rule with its last run, status and alert count. From there you open a rule to edit the query or actions, toggle it off during tuning, run it immediately to test, delete it, or jump to the alerts it generated. Managing rules requires the Security settings (manage) permission or Security Administrator; Security Operators need the manage security settings grant under RBAC."},
 {c:"detect",obj:"1.4.2",q:"Custom detection rule scope — device groups",a:"#Rules can be limited to selected device groups\nUsers only see rules for groups they can access",s:"Limit the rule to chosen device groups",
  x:"When a query touches device data you can restrict the detection to specific device groups so alerts and actions apply only there, which also keeps RBAC-scoped analysts from seeing or editing rules outside their groups. Stem signal: 'the rule must only act on the Finance workstations' or 'the regional team cannot find the rule' — both are scope questions, not query questions."},
 {c:"detect",obj:"1.4.2",q:"Custom detection vs Sentinel analytics rule",a:"#Custom detection: Defender XDR tables, Defender actions, Defender incidents\nAnalytics rule: any workspace table, Sentinel incidents, playbooks",s:"XDR-native detection versus SIEM-side rule",
  x:"Both turn KQL into alerts. A custom detection lives in the Defender portal, queries Defender XDR hunting tables (and, in unified SecOps, Sentinel tables), and can fire Defender response actions. A Sentinel analytics rule runs in the workspace, supports any ingested table, richer scheduling and grouping, and drives automation rules and playbooks. The stem's data source and desired response pick the tool."},
 {c:"detect",obj:"1.4.3",q:"Analytics rule type: Scheduled",a:"#KQL runs on an interval over a lookback window; threshold decides alerts\nMost common and most configurable type",s:"Interval-based KQL query with a threshold",g:"ruletype",
  x:"Scheduled rules are the workhorse: a query, a frequency from 5 minutes to 14 days, a lookback up to 14 days, and a threshold on the number of results. They support entity mapping, custom details, dynamic alert details, event grouping, alert-to-incident grouping and suppression. Content hub templates are mostly scheduled rules. Stem signal: a KQL detection that does not need second-level latency."},
 {c:"detect",obj:"1.4.3",q:"Analytics rule type: Near-real-time (NRT)",a:"#Runs every minute on just-ingested data with a 2-minute built-in delay\nMax 50 per workspace; sources must ingest in under 12 hours",s:"One-minute cadence rule for fast detection",g:"ruletype",
  x:"NRT rules are scheduled rules with a fixed one-minute cadence, keyed on ingestion time rather than TimeGenerated so they catch events as they land. Limits still apply: no more than 50 per customer, log sources whose ingestion delay is under 12 hours, and event grouping capped at 30 single-event alerts per run. Multi-table and cross-workspace queries are now allowed. Stem signal: 'alert within a minute or two'.",
  w:"NRT: every minute, 50 max, grouping capped at 30."},
 {c:"detect",obj:"1.4.3",q:"Analytics rule type: Microsoft security (incident creation)",a:"#Creates Sentinel incidents from alerts of other Microsoft products in real time\nNot available once Defender XDR integration or Defender portal onboarding is on",s:"Turns Microsoft product alerts into incidents",g:"ruletype",
  x:"Microsoft incident creation rules take alerts from services such as Defender for Cloud, Entra ID Protection or the standalone Defender product connectors and open Sentinel incidents, optionally filtered by severity or alert name. With the Defender XDR connector's incident sync or unified SecOps onboarding, they are redundant and must be turned off to avoid duplicates. Stem signal: 'incidents appear twice'."},
 {c:"detect",obj:"1.4.3",q:"Analytics rule type: Fusion (advanced multistage attack detection)",a:"#ML correlates low-fidelity signals across products into high-fidelity incidents\nOne per workspace, on by default; unavailable with Defender integration",s:"Built-in ML correlation rule, one per workspace",g:"ruletype",
  x:"Fusion is Microsoft's correlation engine that joins weak signals — an anomalous sign-in, then a suspicious download, then mass deletion — into a single multistage incident. It is enabled out of the box, cannot be duplicated, and is superseded by Defender XDR correlation when the workspace is integrated or onboarded to the Defender portal. Stem signal: 'detect multistage attacks spanning Entra and endpoint data without writing KQL'."},
 {c:"detect",obj:"1.4.3",q:"Analytics rule type: Threat Intelligence",a:"#Matches CEF, Syslog and Windows DNS events against Microsoft threat indicators\nOne non-customizable rule; high-fidelity alerts",s:"Auto-matches logs against Microsoft indicators",g:"ruletype",
  x:"The Threat Intelligence rule is a single built-in detection that compares network and DNS events with Microsoft-curated domains, IPs and URLs and raises alerts enriched with Defender Threat Intelligence context. It has no editable query. Do not confuse it with the scheduled TI map templates, which match your own ThreatIntelIndicators against chosen tables and are fully customizable."},
 {c:"detect",obj:"1.4.3",q:"Analytics rule type: ML behavior analytics",a:"#Anomalous SSH and RDP logon detection from IP, geo and user history\nBuilt-in, non-customizable",s:"Built-in SSH/RDP anomaly detection",g:"ruletype",
  x:"ML behavior analytics rules are Microsoft-trained models that flag unusual SSH or RDP logins based on where the user normally connects from and when. They ship as unique rule templates you simply enable, and they require the corresponding Syslog or SecurityEvent data. Stem signal: 'detect unusual remote logons without defining thresholds'."},
 {c:"detect",obj:"1.4.3",q:"Scheduled rule: Run every / Lookup data from the last",a:"#Frequency 5 min–14 days; lookback 5 min–14 days; lookback ≥ frequency\n5-minute ingestion delay is added automatically",s:"Frequency and lookback, lookback not shorter than frequency",
  x:"The two scheduling fields set how often the query executes and how far back each run looks. A lookback shorter than the frequency leaves gaps; a lookback longer than the frequency re-examines events and can alert twice. Sentinel also shifts the window by five minutes to absorb ingestion latency. Stem signal: 'the rule missed events that occurred between runs' — lookback is too short."},
 {c:"detect",obj:"1.4.3",q:"Scheduled rule: Alert threshold",a:"#Alert when results are greater than / fewer than / equal to N\nEvaluated per run, not cumulatively",s:"Result-count condition per execution",
  x:"The threshold decides whether a run's row count creates an alert. The default is greater than 0, but you can require, for example, more than 20 results for noisy queries, or fewer than 1 to alert when expected heartbeat data stops arriving. The count is per execution. Stem signal: 'alert when the backup job stops logging' uses a fewer-than threshold."},
 {c:"detect",obj:"1.4.3",q:"Scheduled rule: Event grouping",a:"#Group all events into a single alert (default) or trigger an alert for each event\nPer-event capped at 150 alerts per run",s:"One alert per run versus one alert per row",
  x:"Event grouping chooses between a single summary alert containing all rows and separate alerts per row. Per-event grouping gives one alert, entity set and incident per result, which is useful when each row is a different victim, but a run producing more than 150 rows yields 149 individual alerts plus one summarizing the rest. Stem signal: 'a separate incident for each affected user'.",
  w:"Per-event grouping: 149 + 1 summary at the cap."},
 {c:"detect",obj:"1.4.3",q:"Scheduled rule: Entity mapping",a:"#Map query columns to entity types: Account, Host, IP, URL, File hash…\nUp to 10 entities, 3 identifiers each",s:"Columns bound to entity types for investigation",
  x:"Entity mapping tells Sentinel which columns are the account, host, IP address and so on, so alerts populate the Entities field, the investigation graph links them, UEBA enriches them and automation rule conditions and entity playbooks can use them. A rule can map up to ten entities with up to three identifiers each. Stem signal: 'the incident shows no entities' means mapping was skipped."},
 {c:"detect",obj:"1.4.3",q:"Scheduled rule: Custom details and alert details override",a:"#Custom details: surface up to 20 query fields in the alert\nAlert details: dynamic name, description, severity, tactics from columns",s:"Surface fields and make title/severity dynamic",
  x:"Custom details carry chosen columns into the alert's extended properties for analysts and automation conditions. Alert details override replaces the static rule name, description, severity or tactics with values drawn from the row, so one rule can produce a High alert for admins and Medium for others. Stem signal: 'severity should depend on the user's role column'."},
 {c:"detect",obj:"1.4.3",q:"Scheduled rule: Incident settings and alert grouping",a:"#Create incidents on/off; group related alerts into one incident\nBy all entities, selected entities/details, or all alerts from the rule; window up to 7 days",s:"Decide if and how alerts become incidents",
  x:"Incident settings control whether each alert opens an incident and whether alerts from the rule are consolidated. Grouping can require matching on all mapped entities, on selected entities and custom details, or simply bundle every alert from the rule within a time window from 5 minutes to 7 days, with up to 150 alerts per incident. Stem signal: 'one incident per attacked host rather than per attempt' is grouping on the Host entity."},
 {c:"detect",obj:"1.4.3",q:"Scheduled rule: Suppression",a:"#Stop running the query for a period after an alert fires\nUp to 24 hours",s:"Pause the rule after it alerts",
  x:"Suppression stops the rule from executing for a chosen interval once it has produced an alert, preventing a burst of identical alerts from a continuing condition. The maximum pause is 24 hours. It is a rule-level control, unlike automation rules that close incidents or XDR alert tuning that hides alerts. Stem signal: 'after alerting, do not alert again for the next 12 hours'."},
 {c:"detect",obj:"1.4.3",q:"Validating the KQL in the analytics rule wizard",a:"#Wizard checks syntax and shows Results simulation over the last 50 runs\nQueries cannot use search * or union *",s:"Built-in syntax check plus results simulation",
  x:"The rule wizard will not save a query with syntax errors, and the Results simulation panel charts how many results the query would have produced over recent intervals so you can tune frequency and threshold before enabling. Queries must be 1 to 10,000 characters and cannot use search * or union *. Stem signal: 'estimate how noisy the rule will be before turning it on'."},
 {c:"detect",obj:"1.4.3",q:"Rule templates in the content hub",a:"#Solutions install analytics rule templates; create rules from them\nTemplates list required data connectors",s:"Prebuilt detections installed with solutions",
  x:"Microsoft and partner solutions in the content hub include analytics rule templates. After installing a solution you create active rules from its templates, adjusting schedule, threshold and automation; the template shows which connectors must be streaming. Stem signal: 'use Microsoft-provided detections for Palo Alto logs' is install solution, then enable templates."},
 {c:"detect",obj:"1.4.3",q:"Analytics rule health — SentinelHealth",a:"#Enable Auditing and health monitoring; rule runs log to SentinelHealth\nSuccess or Failure with reasons; changes audited in SentinelAudit",s:"Rule execution status in SentinelHealth",
  x:"After turning on health monitoring under Settings, each scheduled and NRT rule run writes a SentinelHealth record with status and reason, such as a missing table, timeout or semantic error, queryable with _SentinelHealth(). SentinelAudit separately records who changed a rule and what. Stem signal: 'find analytics rules that are failing to run'.",k:"_SentinelHealth()\n| where SentinelResourceType == \"Analytics Rule\"\n| where Status == \"Failure\""},
 {c:"detect",obj:"1.4.4",q:"MITRE ATT&CK page — active vs simulated coverage",a:"#Active: techniques covered by enabled scheduled/NRT rules\nSimulated: what templates and hunting queries could add",s:"Enabled rules versus potential coverage",
  x:"The MITRE ATT&CK blade draws the tactic-and-technique matrix and shades each technique by how many active detections map to it. Switching on simulated coverage adds rule templates and hunting queries you have not enabled, revealing the gap between current and possible coverage. Stem signal: 'identify techniques with no active detection' or 'what coverage would we gain by enabling templates'.",
  w:"Active = what you have; simulated = what you could have."},
 {c:"detect",obj:"1.4.4",q:"How a rule gets onto the MITRE matrix",a:"#Tactics and techniques are assigned in the rule or hunting query settings\nIncidents inherit them from alerts",s:"Techniques are tagged on rules and queries",
  x:"Coverage is only as good as tagging: each analytics rule and hunting query has a MITRE tactics and techniques selection, and the matrix counts those tags. Incidents inherit the techniques of their alerts, which is also what SOC optimization's threat-based recommendations use. Stem signal: 'the detection exists but the matrix shows the technique as uncovered' means the rule is not tagged."},
 {c:"detect",obj:"1.4.5",q:"Anomaly rules — what they produce",a:"#ML baselines write anomaly records to the Anomalies table\nEnabled by default; no alerts on their own",s:"Baseline deviations stored in Anomalies",
  x:"Customizable anomaly rules run machine-learning models over sources such as sign-ins, Office activity and network data, scoring deviations from learned baselines. Results land in the Anomalies table rather than as alerts, where hunting queries, scheduled rules and Fusion can consume them. They are on by default in Production mode. Stem signal: 'use anomaly scores as evidence in a scheduled detection'.",k:"Anomalies\n| where AnomalyTemplateName has \"Login\"\n| where Score > 0.8"},
 {c:"detect",obj:"1.4.5",q:"Tuning an anomaly rule",a:"#Duplicate the built-in rule, edit thresholds/parameters, run in Flighting, then switch to Production\nOnly one customized copy per rule",s:"Duplicate, adjust, flight, then promote",
  x:"Built-in anomaly rules cannot be edited directly. You duplicate one, which creates a disabled copy marked Flighting, adjust its parameters and threshold, enable it and compare results in the Anomalies table, then promote it to Production, which moves the original into Flighting. Each template allows one customized copy. Stem signal: 'too many anomalies from the sign-in model' — duplicate and raise the threshold."},
];
